        self.report_surface_force_n = ti.Vector.field(3, dtype=ti.f32, shape=())
        self.report_grid_force_n = ti.Vector.field(3, dtype=ti.f32, shape=())
        # total fluid force on the obstacle-mask surface (pressure/form part),
