    def save_state(self) -> None:
        self._require_hibm_marker_compatibility_closure_complete()
        self._save_state_kernel()
        self._sst_saved_wall_distance_valid = bool(self._sst_wall_distance_valid)
        self._sst_saved_wall_distance_cache_key = self._sst_wall_distance_cache_key
        self._sst_saved_no_slip_domain_walls = tuple(
            self._sst_no_slip_domain_walls
        )
        self._sst_saved_no_slip_domain_wall_mask = int(
            self.sst_no_slip_domain_wall_mask[None]
        )
        self._saved_hibm_dynamic_solid_volume_enabled = bool(
            self.hibm_dynamic_solid_volume_enabled
        )

    def restore_state(self) -> None:
        # Restore writes obstacle, dynamic-volume, carve, and canonical-row
        # fields.  Retire every derived host contract before the kernel so a
        # partial restore cannot leave old reachability or a seal reusable.
        self.hibm_external_obstacle_topology_revision += 1
        self._invalidate_external_obstacle_topology_derived_state()
        self._restore_state_kernel()
        self._clear_hibm_pressure_outlet_classification_kernel()
        self._sst_no_slip_domain_walls = tuple(
            self._sst_saved_no_slip_domain_walls
        )
        self.sst_no_slip_domain_wall_mask[None] = int(
            self._sst_saved_no_slip_domain_wall_mask
        )
        self._sst_wall_distance_valid = bool(self._sst_saved_wall_distance_valid)
        restored_cache_key = self._sst_saved_wall_distance_cache_key
        if restored_cache_key is not None:
            # Checkpoint codecs preserve named tuples as plain tuples.
            restored_cache_key = _SSTWallDistanceCacheKey(*restored_cache_key)._replace(
                obstacle_topology_revision=int(
                    self.hibm_external_obstacle_topology_revision
                )
            )
        self._sst_wall_distance_cache_key = (
            restored_cache_key if self._sst_wall_distance_valid else None
        )
        # The snapshot stores the published combined field, not the scratch
        # field that owns the obstacle/domain-only base.  Rebuild that base if
        # a later marker overlay changes after rollback.
        self._sst_wall_distance_base_cache_key = None
        self.hibm_dynamic_solid_volume_enabled = bool(
            self._saved_hibm_dynamic_solid_volume_enabled
        )
        self._hibm_pressure_unreached_count = 0
        self.last_hibm_pressure_unreached_cell_count = 0
        self.last_hibm_pressure_unreached_raw_cell_count = 0
        self._hibm_pressure_unreached_component_count = 0
        self.last_hibm_pressure_unreached_component_count = 0
        self.last_hibm_pressure_unreached_component_overflow = False
        self._reset_hibm_pressure_unreached_component_distribution_stats()
        self.last_hibm_pressure_reachability_converged = True
        self.last_hibm_pressure_reachability_sweeps = 0
        self.last_hibm_pressure_reachability_reused = False
        self.last_hibm_pressure_component_labels_converged = True
        self.last_hibm_unreached_cells_with_interface_diagonal = 0
        self.last_hibm_unreached_cells_with_interface_coupling = 0
        self.last_hibm_unreached_components_with_interface_hits = 0
        self.last_hibm_unreached_incompatible_component_count = 0
        self.last_hibm_unreached_component_rhs_mean_max_abs = 0.0
        self.last_hibm_unreached_component_rhs_integral_max_abs = 0.0
        self.last_hibm_solid_band_marked_increment = 0
        self.last_hibm_solid_band_interior_cells = -1
        self.last_hibm_solid_band_enclosed_water_cells = -1
        self.last_hibm_solid_band_velocity_dirichlet_protected_cells = -1
        self.last_hibm_solid_band_mask_protected_cells = -1
        self.last_hibm_pressure_filled_cell_count = -1
        self.last_hibm_air_backed_cell_count = -1
        self.last_hibm_air_backed_component_count = -1
        self.last_hibm_air_backed_cell_volume_m3 = -1.0
        self.last_hibm_row_cloud_orphan_cell_count = 0
