    @ti.kernel
    def _clear_pressure_interface_matrix_terms_kernel(self):
        self.pressure_interface_row_count[None] = 0
        for row in self.pressure_interface_row_support_count:
            self.pressure_interface_row_support_count[row] = 0
            self.pressure_interface_row_source_node[row] = ti.Vector([-1, -1, -1])
        for i, j, k in self.pressure_interface_matrix_diagonal:
            self.pressure_interface_matrix_diagonal[i, j, k] = 0.0
            self.pressure_interface_matrix_rhs[i, j, k] = 0.0
            # The applied interface flux belongs to the current velocity state.
            # Row reassembly must preserve it for a homogeneous increment;
            # a new full projection or state restore clears it explicitly.
            self.pressure_interface_coupling_active[i, j, k] = 0
            self.pressure_interface_coupling_neighbor[i, j, k] = ti.Vector([0, 0, 0])
            self.pressure_interface_coupling_coefficient[i, j, k] = 0.0
            self.pressure_interface_row_diagonal_density[i, j, k] = 0.0
            for slot in ti.static(range(PRESSURE_INTERFACE_COUPLING_EXTRA_SLOTS)):
                self.pressure_interface_coupling_extra_neighbor[
                    i,
                    j,
                    k,
                    slot,
                ] = ti.Vector([0, 0, 0])
                self.pressure_interface_coupling_extra_coefficient[
                    i,
                    j,
                    k,
                    slot,
                ] = 0.0

    def clear_pressure_interface_matrix_terms(self) -> None:
        self._invalidate_pressure_nullspace_component_graph()
        self._clear_pressure_interface_matrix_terms_kernel()

    @ti.kernel
    def _clear_pressure_interface_matrix_rhs_kernel(self):
        for i, j, k in self.pressure_interface_matrix_rhs:
            self.pressure_interface_matrix_rhs[i, j, k] = 0.0

    @ti.kernel
    def _clear_pressure_interface_projection_divergence_kernel(self):
        for i, j, k in self.pressure_interface_projection_divergence_s:
            self.pressure_interface_projection_divergence_s[i, j, k] = 0.0

    @ti.kernel
    def _clear_rowless_pressure_interface_projection_divergence_kernel(self):
        # Every cell an interface row touches receives a positive diagonal.
        # A cell with no interface term after the rows were rebuilt for a new
        # geometry (it left the IB band) has no interface flux left to
        # balance the one applied before, so its face divergence must be
        # corrected by this increment instead of being hidden by the carry.
        for i, j, k in self.pressure_interface_projection_divergence_s:
            if (
                self.pressure_interface_matrix_diagonal[i, j, k] == 0.0
                and self.pressure_interface_matrix_rhs[i, j, k] == 0.0
            ):
                self.pressure_interface_projection_divergence_s[i, j, k] = 0.0

    @classmethod
    def _validated_velocity_dirichlet_boundary_authority(
        cls,
        authority: object,
    ) -> str:
        if not isinstance(authority, str):
            raise TypeError(
                "velocity Dirichlet boundary authority must be 'legacy' or "
                "'canonical'"
            )
        if authority not in cls._VELOCITY_DIRICHLET_BOUNDARY_AUTHORITIES:
            raise ValueError(
                "velocity Dirichlet boundary authority must be 'legacy' or "
                f"'canonical', got {authority!r}"
            )
        return authority

    def _velocity_dirichlet_boundary_authority_code(self) -> int:
        return (
            1
            if self._validated_velocity_dirichlet_boundary_authority(
                self.velocity_dirichlet_boundary_authority
            )
            == "canonical"
            else 0
        )

    def set_velocity_dirichlet_boundary_authority(self, authority: object) -> None:
        authority_name = self._validated_velocity_dirichlet_boundary_authority(
            authority
        )
        if (
            authority_name == "canonical"
            and int(self.velocity_dirichlet_face_symmetric) != 0
        ):
            raise ValueError(
                "canonical velocity Dirichlet boundary authority forbids the "
                "legacy velocity_dirichlet_face_symmetric compatibility path"
            )
        authority_code = 1 if authority_name == "canonical" else 0
        if authority_name == self.velocity_dirichlet_boundary_authority:
            self.velocity_dirichlet_boundary_authority_code_device[None] = (
                authority_code
            )
            return
        # Authority participates in both pressure connectivity and the exact
        # interface operator graph. Invalidate both before changing either the
        # host identity or its device mirror.
        self._invalidate_hibm_pressure_reachability()
        self._invalidate_velocity_dirichlet_component_ledger()
        self.velocity_dirichlet_boundary_authority = authority_name
        self.velocity_dirichlet_boundary_authority_code_device[None] = authority_code

    def _invalidate_velocity_dirichlet_component_ledger(self) -> int:
        # Retire host authority before the first fallible device operation.
        generation = int(self.velocity_dirichlet_component_ledger_generation) + 1
        self.velocity_dirichlet_component_ledger_generation = generation
        self.velocity_dirichlet_component_ledger_sealed = False
        self._velocity_dirichlet_component_ledger_consumer_generations = {}
        self._velocity_dirichlet_component_ledger_consumer_capabilities = {}
        self._invalidate_pressure_nullspace_component_graph()
        try:
            object.__getattribute__(
                self,
                "canonical_exact_hard_face_component_mask",
            )
        except AttributeError:
            # Host-only contract probes construct an intentionally incomplete
            # owner; production solvers always own and clear this device mask.
            pass
        else:
            self._clear_canonical_exact_hard_face_component_mask_kernel()
        return generation

    def _register_velocity_dirichlet_component_ledger_consumer_generation(
        self,
        consumer: str,
        *,
        capability: object,
    ) -> None:
        if consumer not in self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMERS:
            raise ValueError(
                f"unknown canonical velocity boundary consumer {consumer!r}"
            )
        expected_capability = (
            self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES.get(
                consumer
            )
        )
        if expected_capability is None or capability is not expected_capability:
            raise RuntimeError(
                "canonical velocity boundary consumer is not backed by its "
                f"dedicated migrated prepare capability: {consumer!r}"
            )
        generation_value = int(
            self.velocity_dirichlet_component_ledger_generation
        )
        self._velocity_dirichlet_component_ledger_consumer_generations = {
            **self._velocity_dirichlet_component_ledger_consumer_generations,
            consumer: int(generation_value),
        }
        self._velocity_dirichlet_component_ledger_consumer_capabilities = {
            **self._velocity_dirichlet_component_ledger_consumer_capabilities,
            consumer: capability,
        }

    def _velocity_dirichlet_component_ledger_generation_errors(
        self,
    ) -> tuple[list[str], list[str], list[str], list[str]]:
        registered = self._velocity_dirichlet_component_ledger_consumer_generations
        registered_capabilities = getattr(
            self,
            "_velocity_dirichlet_component_ledger_consumer_capabilities",
            {},
        )
        required = self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMERS
        missing = sorted(required - set(registered))
        unexpected = sorted(set(registered) - required)
        generation = int(self.velocity_dirichlet_component_ledger_generation)
        mismatched = sorted(
            consumer
            for consumer in required & set(registered)
            if int(registered[consumer]) != generation
        )
        invalid_capabilities = sorted(
            consumer
            for consumer in required & set(registered)
            if (
                self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES.get(
                    consumer
                )
                is None
                or registered_capabilities.get(consumer)
                is not self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES.get(
                    consumer
                )
            )
        )
        return missing, unexpected, mismatched, invalid_capabilities

    def _require_host_macro_step_restore_complete(self) -> None:
        if getattr(self, "_host_macro_step_restore_pending", False):
            raise RuntimeError("host macro-step restore is incomplete")

    def _require_hibm_marker_compatibility_closure_complete(self) -> None:
        CartesianFluidSolver._require_host_macro_step_restore_complete(self)
        if bool(getattr(self, "_hibm_marker_compatibility_closure_pending", False)):
            raise RuntimeError(
                "HIBM marker compatibility closure is pending; "
                "intermediate band geometry cannot be sealed or consumed"
            )

    def seal_velocity_dirichlet_component_ledger(self) -> None:
        self._require_hibm_marker_compatibility_closure_complete()
        authority = self._validated_velocity_dirichlet_boundary_authority(
            self.velocity_dirichlet_boundary_authority
        )
        if authority != "canonical":
            raise RuntimeError(
                "only canonical velocity Dirichlet boundary authority can seal "
                "the component ledger"
            )
        if int(self.velocity_dirichlet_face_symmetric) != 0:
            raise RuntimeError(
                "canonical velocity Dirichlet boundary authority forbids the "
                "legacy velocity_dirichlet_face_symmetric compatibility path"
            )
        missing, unexpected, mismatched, invalid_capabilities = (
            self._velocity_dirichlet_component_ledger_generation_errors()
        )
        if missing or unexpected or mismatched or invalid_capabilities:
            self.velocity_dirichlet_component_ledger_sealed = False
            raise RuntimeError(
                "canonical velocity Dirichlet component ledger consumer "
                "generations are incomplete or mismatched: "
                f"missing={missing}, unexpected={unexpected}, "
                f"mismatched={mismatched}, invalid_capabilities="
                f"{invalid_capabilities}, generation="
                f"{int(self.velocity_dirichlet_component_ledger_generation)}"
            )
        self._refresh_canonical_exact_hard_face_component_mask()
        self.velocity_dirichlet_component_ledger_sealed = True

    def _require_velocity_dirichlet_component_ledger_sealed(self) -> None:
        self._require_hibm_marker_compatibility_closure_complete()
        authority = self._validated_velocity_dirichlet_boundary_authority(
            self.velocity_dirichlet_boundary_authority
        )
        if authority == "legacy":
            return
        if int(self.velocity_dirichlet_face_symmetric) != 0:
            raise RuntimeError(
                "canonical velocity Dirichlet boundary authority forbids the "
                "legacy velocity_dirichlet_face_symmetric compatibility path"
            )
        missing, unexpected, mismatched, invalid_capabilities = (
            self._velocity_dirichlet_component_ledger_generation_errors()
        )
        if (
            not bool(self.velocity_dirichlet_component_ledger_sealed)
            or missing
            or unexpected
            or mismatched
            or invalid_capabilities
        ):
            raise RuntimeError(
                "canonical velocity Dirichlet component ledger is not sealed "
                "for its current generation"
            )

    def _require_legacy_velocity_dirichlet_boundary_authority(self) -> None:
        authority = self._validated_velocity_dirichlet_boundary_authority(
            self.velocity_dirichlet_boundary_authority
        )
        if authority != "legacy":
            raise RuntimeError(
                "canonical velocity Dirichlet boundary authority forbids this "
                "legacy boundary writer"
            )

    def _require_canonical_velocity_dirichlet_boundary_authority(self) -> None:
        authority = self._validated_velocity_dirichlet_boundary_authority(
            self.velocity_dirichlet_boundary_authority
        )
        if authority != "canonical":
            raise RuntimeError(
                "legacy velocity Dirichlet boundary authority forbids this "
                "canonical boundary writer"
            )

    def prepare_velocity_dirichlet_component_ledger_apply(self) -> None:
        """Register the migrated componentwise boundary-application consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "apply",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "apply"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_reference(self) -> None:
        """Register the exact eight-field canonical reference consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "reference",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "reference"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_snapshot(self) -> None:
        """Register the exact schema-6 canonical snapshot consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "snapshot",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "snapshot"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_fv_operator(self) -> None:
        """Register the migrated fine-grid FV pressure-operator consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "fv_operator",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "fv_operator"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_gradient(self) -> None:
        """Register the migrated componentwise pressure-gradient consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "gradient",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "gradient"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_divergence(self) -> None:
        """Register the migrated axis-local divergence consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "divergence",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "divergence"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_reachability(self) -> None:
        """Build and register the axis-local pressure-connectivity consumer."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        # The flood consumes this derived component-face mask.  Rebuild it
        # before certifying the consumer and invalidate every older flood result:
        # neither a checksum nor ``last_*_valid`` certifies this generation.
        self._refresh_velocity_dirichlet_pressure_hard_fixed_component_mask()
        self._invalidate_hibm_pressure_reachability()
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "reachability",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "reachability"
            ],
        )

    @ti.func
    def _canonical_multigrid_fine_face_index(
        self,
        coarse_i: ti.i32,
        coarse_j: ti.i32,
        coarse_k: ti.i32,
        component_axis: ti.i32,
        transverse_offset_a: ti.i32,
        transverse_offset_b: ti.i32,
        factor_x: ti.i32,
        factor_y: ti.i32,
        factor_z: ti.i32,
    ):
        """Map a coarse MAC face to one coplanar fine subface."""

        fine_i = factor_x * coarse_i
        fine_j = factor_y * coarse_j
        fine_k = factor_z * coarse_k
        if component_axis == 0:
            fine_j += transverse_offset_a
            fine_k += transverse_offset_b
        elif component_axis == 1:
            fine_i += transverse_offset_a
            fine_k += transverse_offset_b
        else:
            fine_i += transverse_offset_a
            fine_j += transverse_offset_b
        return ti.Vector([fine_i, fine_j, fine_k])

    @ti.kernel
    def _build_canonical_velocity_dirichlet_multigrid_level_kernel(
        self,
        fine_active_component_mask: ti.template(),
        fine_pressure_mobility: ti.template(),
        fine_hard_fixed_component_mask: ti.template(),
        fine_owned_component_mask: ti.template(),
        fine_external_exact_component_mask: ti.template(),
        fine_cell_width_x_m: ti.template(),
        fine_cell_width_y_m: ti.template(),
        fine_cell_width_z_m: ti.template(),
        coarse_active_component_mask: ti.template(),
        coarse_pressure_mobility: ti.template(),
        coarse_hard_fixed_component_mask: ti.template(),
        coarse_owned_component_mask: ti.template(),
        coarse_external_exact_component_mask: ti.template(),
        coarse_pressure_hard_fixed_component_mask: ti.template(),
        fine_nx: ti.i32,
        fine_ny: ti.i32,
        fine_nz: ti.i32,
        factor_x: ti.i32,
        factor_y: ti.i32,
        factor_z: ti.i32,
    ):
        for i, j, k in coarse_active_component_mask:
            active_mask = 0
            hard_mask = 0
            owned_mask = 0
            external_mask = 0
            coarse_mobility = ti.Vector([1.0, 1.0, 1.0])
            invalid_contract = 0
            for component_axis in ti.static(range(3)):
                component_bit = 1 << component_axis
                # transverse coarsening factors of this face orientation
                transverse_factor_a = factor_y if component_axis == 0 else factor_x
                transverse_factor_b = factor_z if component_axis != 2 else factor_y
                total_area = ti.cast(0.0, ti.f64)
                weighted_pressure_mobility = ti.cast(0.0, ti.f64)
                valid_count = 0
                active_count = 0
                hard_count = 0
                owned_count = 0
                external_count = 0
                for transverse_offset_a, transverse_offset_b in ti.static(
                    ti.ndrange(2, 2)
                ):
                    fine_index = self._canonical_multigrid_fine_face_index(
                        i,
                        j,
                        k,
                        component_axis,
                        transverse_offset_a,
                        transverse_offset_b,
                        factor_x,
                        factor_y,
                        factor_z,
                    )
                    fine_i = fine_index.x
                    fine_j = fine_index.y
                    fine_k = fine_index.z
                    if (
                        transverse_offset_a < transverse_factor_a
                        and transverse_offset_b < transverse_factor_b
                        and fine_i < fine_nx
                        and fine_j < fine_ny
                        and fine_k < fine_nz
                    ):
                        valid_count += 1
                        area = ti.cast(1.0, ti.f64)
                        if component_axis == 0:
                            area = ti.cast(
                                fine_cell_width_y_m[fine_j], ti.f64
                            ) * ti.cast(fine_cell_width_z_m[fine_k], ti.f64)
                        elif component_axis == 1:
                            area = ti.cast(
                                fine_cell_width_x_m[fine_i], ti.f64
                            ) * ti.cast(fine_cell_width_z_m[fine_k], ti.f64)
                        else:
                            area = ti.cast(
                                fine_cell_width_x_m[fine_i], ti.f64
                            ) * ti.cast(fine_cell_width_y_m[fine_j], ti.f64)
                        if (
                            area <= 0.0
                            or ti.math.isnan(area)
                            or ti.math.isinf(area)
                        ):
                            invalid_contract = 1
                            area = ti.cast(0.0, ti.f64)
                        is_active = (
                            fine_active_component_mask[fine_i, fine_j, fine_k]
                            & component_bit
                        ) != 0
                        is_hard = (
                            fine_hard_fixed_component_mask[
                                fine_i, fine_j, fine_k
                            ]
                            & component_bit
                        ) != 0
                        is_owned = (
                            fine_owned_component_mask[fine_i, fine_j, fine_k]
                            & component_bit
                        ) != 0
                        is_external = (
                            fine_external_exact_component_mask[
                                fine_i, fine_j, fine_k
                            ]
                            & component_bit
                        ) != 0
                        mobility = fine_pressure_mobility[
                            fine_i, fine_j, fine_k
                        ][component_axis]
                        if ti.math.isnan(mobility) or ti.math.isinf(mobility):
                            invalid_contract = 1
                            mobility = 0.0
                        pressure_weight = ti.cast(1.0, ti.f64)
                        if is_active:
                            active_count += 1
                            if is_hard:
                                hard_count += 1
                                pressure_weight = ti.cast(0.0, ti.f64)
                            else:
                                pressure_weight = ti.cast(
                                    ti.min(ti.max(mobility, 0.0), 1.0),
                                    ti.f64,
                                )
                            if is_owned:
                                owned_count += 1
                            if is_external:
                                external_count += 1
                            if is_owned and is_external:
                                invalid_contract = 1
                        elif is_hard or is_owned or is_external:
                            invalid_contract = 1
                        total_area += area
                        weighted_pressure_mobility += area * pressure_weight
                if valid_count <= 0 or total_area <= 0.0:
                    invalid_contract = 1
                else:
                    coarse_mobility[component_axis] = ti.cast(
                        weighted_pressure_mobility / total_area,
                        ti.f32,
                    )
                    if active_count > 0:
                        active_mask |= component_bit
                    if hard_count == valid_count:
                        hard_mask |= component_bit
                    if owned_count == valid_count:
                        owned_mask |= component_bit
                    if external_count == valid_count:
                        external_mask |= component_bit
                    elif external_count > 0:
                        invalid_contract = 1
            if invalid_contract != 0:
                # Canonical masks reserve only bits 0..2.  A sentinel bit lets
                # the later validation pass fail closed without host copies.
                active_mask |= 8
            coarse_active_component_mask[i, j, k] = active_mask
            coarse_pressure_mobility[i, j, k] = coarse_mobility
            coarse_hard_fixed_component_mask[i, j, k] = hard_mask
            coarse_owned_component_mask[i, j, k] = owned_mask
            coarse_external_exact_component_mask[i, j, k] = external_mask
            pressure_hard_mask = hard_mask
            if external_mask != 0:
                pressure_hard_mask = hard_mask & (owned_mask | external_mask)
            coarse_pressure_hard_fixed_component_mask[i, j, k] = (
                pressure_hard_mask
            )

    def _build_canonical_velocity_dirichlet_multigrid_level(
        self,
        fine_level: int,
        coarse_level: int,
    ) -> None:
        if coarse_level != fine_level + 1:
            raise ValueError("canonical multigrid levels must be adjacent")
        fine_shape = self._mg_shapes[fine_level]
        self._build_canonical_velocity_dirichlet_multigrid_level_kernel(
            self._mg_velocity_dirichlet_boundary_active_component_mask[fine_level],
            self._mg_velocity_dirichlet_boundary_pressure_mobility[fine_level],
            self._mg_velocity_dirichlet_boundary_hard_fixed_component_mask[
                fine_level
            ],
            self._mg_velocity_dirichlet_boundary_owned_component_mask[fine_level],
            self._mg_velocity_dirichlet_boundary_external_exact_component_mask[
                fine_level
            ],
            self._mg_cell_width_x_m[fine_level],
            self._mg_cell_width_y_m[fine_level],
            self._mg_cell_width_z_m[fine_level],
            self._mg_velocity_dirichlet_boundary_active_component_mask[coarse_level],
            self._mg_velocity_dirichlet_boundary_pressure_mobility[coarse_level],
            self._mg_velocity_dirichlet_boundary_hard_fixed_component_mask[
                coarse_level
            ],
            self._mg_velocity_dirichlet_boundary_owned_component_mask[coarse_level],
            self._mg_velocity_dirichlet_boundary_external_exact_component_mask[
                coarse_level
            ],
            self._mg_velocity_dirichlet_pressure_hard_fixed_component_mask[
                coarse_level
            ],
            int(fine_shape[0]),
            int(fine_shape[1]),
            int(fine_shape[2]),
            int(self._mg_level_factors[fine_level][0]),
            int(self._mg_level_factors[fine_level][1]),
            int(self._mg_level_factors[fine_level][2]),
        )

    @ti.kernel
    def _validate_canonical_velocity_dirichlet_multigrid_level_kernel(
        self,
        active_component_mask: ti.template(),
        pressure_mobility: ti.template(),
        hard_fixed_component_mask: ti.template(),
        owned_component_mask: ti.template(),
        external_exact_component_mask: ti.template(),
    ):
        self.reduction_count[None] = 0
        for i, j, k in active_component_mask:
            active = active_component_mask[i, j, k]
            hard = hard_fixed_component_mask[i, j, k]
            owned = owned_component_mask[i, j, k]
            external = external_exact_component_mask[i, j, k]
            invalid = (
                ((active | hard | owned | external) & ~7) != 0
                or (hard & ~active) != 0
                or (owned & ~active) != 0
                or (external & ~active) != 0
                or (owned & external) != 0
            )
            for component_axis in ti.static(range(3)):
                mobility = pressure_mobility[i, j, k][component_axis]
                if ti.math.isnan(mobility) or ti.math.isinf(mobility):
                    invalid = True
                if mobility < 0.0 or mobility > 1.0:
                    invalid = True
            if invalid:
                ti.atomic_add(self.reduction_count[None], 1)

    def _validate_canonical_velocity_dirichlet_multigrid_level(
        self,
        level: int,
    ) -> int:
        self._validate_canonical_velocity_dirichlet_multigrid_level_kernel(
            self._mg_velocity_dirichlet_boundary_active_component_mask[level],
            self._mg_velocity_dirichlet_boundary_pressure_mobility[level],
            self._mg_velocity_dirichlet_boundary_hard_fixed_component_mask[level],
            self._mg_velocity_dirichlet_boundary_owned_component_mask[level],
            self._mg_velocity_dirichlet_boundary_external_exact_component_mask[level],
        )
        return int(self.reduction_count[None])

    def prepare_velocity_dirichlet_component_ledger_multigrid(self) -> None:
        """Build, validate and register the component-face MG hierarchy."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        for fine_level in range(len(self._mg_shapes) - 1):
            self._build_canonical_velocity_dirichlet_multigrid_level(
                fine_level,
                fine_level + 1,
            )
        for level in range(len(self._mg_shapes)):
            invalid_count = (
                self._validate_canonical_velocity_dirichlet_multigrid_level(level)
            )
            if invalid_count != 0:
                raise RuntimeError(
                    "canonical velocity Dirichlet multigrid level "
                    f"{level} is invalid: invalid_cells={invalid_count}"
                )
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "multigrid",
            capability=self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES[
                "multigrid"
            ],
        )

    def prepare_velocity_dirichlet_component_ledger_projection(self) -> None:
        """Register projection only after every physical child is current."""

        if self.velocity_dirichlet_boundary_authority != "canonical":
            return
        generation = int(self.velocity_dirichlet_component_ledger_generation)
        missing: list[str] = []
        mismatched: list[str] = []
        invalid_capabilities: list[str] = []
        capabilities = self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_CONSUMER_CAPABILITIES
        for consumer in sorted(
            self._VELOCITY_DIRICHLET_COMPONENT_LEDGER_PROJECTION_DEPENDENCIES
        ):
            registered_generation = (
                self._velocity_dirichlet_component_ledger_consumer_generations.get(
                    consumer
                )
            )
            if registered_generation is None:
                missing.append(consumer)
            elif int(registered_generation) != generation:
                mismatched.append(consumer)
            if (
                self._velocity_dirichlet_component_ledger_consumer_capabilities.get(
                    consumer
                )
                is not capabilities[consumer]
            ):
                invalid_capabilities.append(consumer)
        if missing or mismatched or invalid_capabilities:
            raise RuntimeError(
                "canonical projection dependencies are incomplete or stale: "
                f"missing={missing}, mismatched={mismatched}, "
                f"invalid_capabilities={invalid_capabilities}, "
                f"generation={generation}"
            )
        self._register_velocity_dirichlet_component_ledger_consumer_generation(
            "projection",
            capability=capabilities["projection"],
        )

    def prepare_and_seal_velocity_dirichlet_component_ledger(self) -> None:
        """Prepare every canonical consumer and seal the current generation."""

        self._require_hibm_marker_compatibility_closure_complete()
        self._require_canonical_velocity_dirichlet_boundary_authority()
        self._invalidate_hibm_pressure_reachability()
        self.prepare_velocity_dirichlet_component_ledger_apply()
        self.prepare_velocity_dirichlet_component_ledger_divergence()
        self.prepare_velocity_dirichlet_component_ledger_reachability()
        self.prepare_velocity_dirichlet_component_ledger_fv_operator()
        self.prepare_velocity_dirichlet_component_ledger_gradient()
        self.prepare_velocity_dirichlet_component_ledger_multigrid()
        self.prepare_velocity_dirichlet_component_ledger_projection()
        self.prepare_hibm_no_slip_component_face_valid_mask()
        self.prepare_velocity_dirichlet_component_ledger_reference()
        self.prepare_velocity_dirichlet_component_ledger_snapshot()
        self.seal_velocity_dirichlet_component_ledger()
        self._require_velocity_dirichlet_component_ledger_sealed()

    @ti.kernel
    def _clear_velocity_dirichlet_boundary_rows_kernel(self):
        for i, j, k in self.velocity_dirichlet_boundary_active:
            self.velocity_dirichlet_boundary_active[i, j, k] = 0
            self.velocity_dirichlet_boundary_value_mps[i, j, k] = ti.Vector(
                [0.0, 0.0, 0.0]
            )
            self.velocity_dirichlet_boundary_projection_weight[i, j, k] = 0.0
            self.velocity_dirichlet_boundary_enforcement_weight[i, j, k] = 0.0
            self.velocity_dirichlet_boundary_marker_region_id[i, j, k] = -1
            self.velocity_dirichlet_boundary_hard_fixed_component_mask[i, j, k] = 0
            self.velocity_dirichlet_boundary_external_exact_component_mask[
                i, j, k
            ] = 0
            self.velocity_dirichlet_boundary_owned_row[i, j, k] = 0
            self.velocity_dirichlet_boundary_active_component_mask[i, j, k] = 0
            self.velocity_dirichlet_boundary_pressure_mobility[i, j, k] = ti.Vector(
                [1.0, 1.0, 1.0]
            )
            self.velocity_dirichlet_boundary_component_enforcement_weight[
                i, j, k
            ] = ti.Vector([0.0, 0.0, 0.0])
            self.velocity_dirichlet_boundary_component_region_id[
                i, j, k
            ] = ti.Vector([-1, -1, -1])
            self.velocity_dirichlet_boundary_owned_component_mask[i, j, k] = 0
            self.velocity_dirichlet_pressure_hard_fixed_component_mask[i, j, k] = 0
        self.report_velocity_dirichlet_boundary_cells[None] = 0
        self.report_velocity_dirichlet_boundary_delta_sum[None] = 0.0
        self.report_velocity_dirichlet_boundary_delta_max[None] = 0.0
        self.report_velocity_dirichlet_boundary_momentum_delta_n_s[None] = ti.Vector(
            [0.0, 0.0, 0.0]
        )

    def clear_velocity_dirichlet_boundary_rows(self) -> None:
        self._invalidate_hibm_pressure_reachability()
        self._invalidate_velocity_dirichlet_component_ledger()
        self._clear_velocity_dirichlet_boundary_rows_kernel()
        self._hibm_marker_compatibility_closure_pending = False

    @ti.kernel
    def _clear_force_kernel(self):
        for i, j, k in self.force:
            self.force[i, j, k] = ti.Vector([0.0, 0.0, 0.0])
        self.report_surface_force_n[None] = ti.Vector([0.0, 0.0, 0.0])
        self.report_grid_force_n[None] = ti.Vector([0.0, 0.0, 0.0])
        self.report_force_spread_relative_error[None] = 0.0
        self.report_active_force_cells[None] = 0
        self.report_grid_impulse_n_s[None] = ti.Vector([0.0, 0.0, 0.0])
        self.report_momentum_delta_n_s[None] = ti.Vector([0.0, 0.0, 0.0])
        self.report_impulse_relative_error[None] = 0.0
        self.report_active_velocity_cells[None] = 0

    def clear_force(self) -> None:
        self._clear_force_kernel()

    @ti.kernel
    def _clear_volume_source_kernel(self):
        for i, j, k in self.volume_source_s:
            self.volume_source_s[i, j, k] = 0.0

    @ti.kernel
    def _zero_velocity_component_kernel(self, axis: ti.i32):
        for i, j, k in self.velocity:
            self.velocity[i, j, k][axis] = 0.0
            self.velocity_prev[i, j, k][axis] = 0.0

    def enforce_quasi_2d_velocity(self) -> bool:
        """Zero the configured quasi-2D velocity component; returns whether it acted."""
        axis = int(self.quasi_2d_velocity_axis)
        if axis < 0:
            return False
        if axis not in (0, 1, 2):
            raise ValueError("quasi_2d_velocity_axis must be -1, 0, 1 or 2")
        self._zero_velocity_component_kernel(axis)
        return True

    def clear_volume_source(self) -> None:
        self._clear_volume_source_kernel()

    @ti.kernel
    def _add_zmax_velocity_inlet_volume_source_kernel(
        self,
        normal_velocity_mps: ti.f32,
    ):
        k = self.nz - 1
        for i, j in ti.ndrange(self.nx, self.ny):
            self.volume_source_s[i, j, k] += (
                -normal_velocity_mps / self.cell_width_z_m[k]
            )

    def add_zmax_velocity_inlet_volume_source(
        self,
        *,
        normal_velocity_mps: float,
    ) -> None:
        if not math.isfinite(float(normal_velocity_mps)):
            raise ValueError("normal_velocity_mps must be finite")
        self._add_zmax_velocity_inlet_volume_source_kernel(
            float(normal_velocity_mps)
        )

    @ti.kernel
    def _initialize_uniform_sst_state_kernel(
        self,
        turbulent_kinetic_energy_m2_s2: ti.f32,
        specific_dissipation_rate_s: ti.f32,
        eddy_viscosity_pa_s: ti.f32,
    ):
        for i, j, k in self.sst_turbulent_kinetic_energy:
            self.sst_turbulent_kinetic_energy[i, j, k] = (
                turbulent_kinetic_energy_m2_s2
            )
            self.sst_specific_dissipation_rate[i, j, k] = (
                specific_dissipation_rate_s
            )
            self.sst_eddy_viscosity_pa_s[i, j, k] = eddy_viscosity_pa_s

    @ti.kernel
    def _initialize_sst_wall_distance_kernel(
        self,
        no_slip_xmin: ti.i32,
        no_slip_xmax: ti.i32,
        no_slip_ymin: ti.i32,
        no_slip_ymax: ti.i32,
        no_slip_zmin: ti.i32,
        no_slip_zmax: ti.i32,
        fallback_distance_m: ti.f32,
    ):
        self.reduction_count[None] = 0
        for i, j, k in self.sst_wall_distance_m:
            best = fallback_distance_m
            nearest = ti.Vector([-1, -1, -1])
            if self.obstacle[i, j, k] != 0:
                best = 0.0
                nearest = ti.Vector([i, j, k])
                ti.atomic_max(self.reduction_count[None], 1)
            else:
                if no_slip_xmin != 0:
                    best = ti.min(best, self.cell_center_x_m[i] - self.bounds_min[0])
                if no_slip_xmax != 0:
                    best = ti.min(best, self.bounds_max[0] - self.cell_center_x_m[i])
                if no_slip_ymin != 0:
                    best = ti.min(best, self.cell_center_y_m[j] - self.bounds_min[1])
                if no_slip_ymax != 0:
                    best = ti.min(best, self.bounds_max[1] - self.cell_center_y_m[j])
                if no_slip_zmin != 0:
                    best = ti.min(best, self.cell_center_z_m[k] - self.bounds_min[2])
                if no_slip_zmax != 0:
                    best = ti.min(best, self.bounds_max[2] - self.cell_center_z_m[k])
                if i > 0 and self.obstacle[i - 1, j, k] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_x_m[i])
                if i + 1 < self.nx and self.obstacle[i + 1, j, k] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_x_m[i])
                if j > 0 and self.obstacle[i, j - 1, k] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_y_m[j])
                if j + 1 < self.ny and self.obstacle[i, j + 1, k] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_y_m[j])
                if k > 0 and self.obstacle[i, j, k - 1] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_z_m[k])
                if k + 1 < self.nz and self.obstacle[i, j, k + 1] != 0:
                    best = ti.min(best, 0.5 * self.cell_width_z_m[k])
            self.sst_wall_distance_m[i, j, k] = ti.max(best, 1.0e-12)
            self.sst_wall_distance_next_m[i, j, k] = ti.max(best, 1.0e-12)
            self.sst_nearest_obstacle_cell[i, j, k] = nearest
            self.sst_nearest_obstacle_cell_next[i, j, k] = nearest

    @ti.func
    def _sst_distance_to_obstacle_cell(self, position, obstacle_index):
        oi = obstacle_index.x
        oj = obstacle_index.y
        ok = obstacle_index.z
        nearest = ti.Vector(
            [
                ti.min(ti.max(position.x, self.cell_face_x_m[oi]), self.cell_face_x_m[oi + 1]),
                ti.min(ti.max(position.y, self.cell_face_y_m[oj]), self.cell_face_y_m[oj + 1]),
                ti.min(ti.max(position.z, self.cell_face_z_m[ok]), self.cell_face_z_m[ok + 1]),
            ]
        )
        return (position - nearest).norm()

    @ti.kernel
    def _relax_sst_wall_distance_kernel(self, jump: ti.i32):
        self.reduction_count[None] = 0
        for i, j, k in self.sst_wall_distance_m:
            best = self.sst_wall_distance_m[i, j, k]
            best_obstacle = self.sst_nearest_obstacle_cell[i, j, k]
            changed = 0
            if self.obstacle[i, j, k] == 0:
                position = ti.Vector(
                    [
                        self.cell_center_x_m[i],
                        self.cell_center_y_m[j],
                        self.cell_center_z_m[k],
                    ]
                )
                for di, dj, dk in ti.static(ti.ndrange((-1, 2), (-1, 2), (-1, 2))):
                    ni = i + di * jump
                    nj = j + dj * jump
                    nk = k + dk * jump
                    if 0 <= ni < self.nx and 0 <= nj < self.ny and 0 <= nk < self.nz:
                        candidate = self.sst_nearest_obstacle_cell[ni, nj, nk]
                        if candidate.x >= 0:
                            candidate_distance = self._sst_distance_to_obstacle_cell(
                                position, candidate
                            )
                            if candidate_distance < best:
                                best = candidate_distance
                                best_obstacle = candidate
                                changed = 1
            self.sst_wall_distance_next_m[i, j, k] = best
            self.sst_nearest_obstacle_cell_next[i, j, k] = best_obstacle
            if changed != 0:
                ti.atomic_add(self.reduction_count[None], 1)

    @ti.kernel
    def _commit_sst_wall_distance_kernel(self):
        for i, j, k in self.sst_wall_distance_m:
            self.sst_wall_distance_m[i, j, k] = (
                self.sst_wall_distance_next_m[i, j, k]
            )
            self.sst_nearest_obstacle_cell[i, j, k] = (
                self.sst_nearest_obstacle_cell_next[i, j, k]
            )

    @ti.kernel
    def _restore_sst_base_wall_distance_kernel(self):
        for i, j, k in self.sst_wall_distance_m:
            self.sst_wall_distance_m[i, j, k] = (
                self.sst_wall_distance_next_m[i, j, k]
            )

    @ti.kernel
    def _include_sst_marker_wall_distance_kernel(
        self,
        marker_position_m: ti.template(),
        marker_count: ti.i32,
        inactive_axis: ti.i32,
    ):
        for i, j, k in self.sst_wall_distance_m:
            if self.obstacle[i, j, k] == 0:
                position = ti.Vector(
                    [
                        self.cell_center_x_m[i],
                        self.cell_center_y_m[j],
                        self.cell_center_z_m[k],
                    ]
                )
                best = self.sst_wall_distance_m[i, j, k]
                for marker in range(marker_count):
                    delta = position - marker_position_m[marker]
                    if inactive_axis == 0:
                        delta.x = 0.0
                    elif inactive_axis == 1:
                        delta.y = 0.0
                    elif inactive_axis == 2:
                        delta.z = 0.0
                    best = ti.min(best, delta.norm())
                self.sst_wall_distance_m[i, j, k] = ti.max(best, 1.0e-12)

    @ti.kernel
    def _include_sst_projection_segment_wall_distance_kernel(
        self,
        marker_position_m: ti.template(),
        projection_segment_indices: ti.template(),
        projection_segment_count: ti.i32,
        inactive_axis: ti.i32,
    ):
        for i, j, k in self.sst_wall_distance_m:
            if self.obstacle[i, j, k] == 0:
                position = ti.Vector(
                    [
                        self.cell_center_x_m[i],
                        self.cell_center_y_m[j],
                        self.cell_center_z_m[k],
                    ]
                )
                best = self.sst_wall_distance_m[i, j, k]
                for segment_index in range(projection_segment_count):
                    segment = projection_segment_indices[segment_index]
                    endpoint_a = marker_position_m[segment.x]
                    endpoint_b = marker_position_m[segment.y]
                    offset = position - endpoint_a
                    tangent = endpoint_b - endpoint_a
                    if inactive_axis == 0:
                        offset.x = 0.0
                        tangent.x = 0.0
                    elif inactive_axis == 1:
                        offset.y = 0.0
                        tangent.y = 0.0
                    elif inactive_axis == 2:
                        offset.z = 0.0
                        tangent.z = 0.0
                    length_squared = tangent.dot(tangent)
                    segment_fraction = 0.0
                    if length_squared > 1.0e-30:
                        segment_fraction = ti.min(
                            ti.max(offset.dot(tangent) / length_squared, 0.0),
                            1.0,
                        )
                    delta = offset - segment_fraction * tangent
                    best = ti.min(best, delta.norm())
                self.sst_wall_distance_m[i, j, k] = ti.max(best, 1.0e-12)

    def _sst_wall_distance_input_identity(
        self,
        *,
        wall_flags: tuple[bool, bool, bool, bool, bool, bool],
        marker_position_m: object | None,
        marker_count: object,
        projection_segment_indices: object | None,
        projection_segment_count: object,
        inactive_axis: int,
    ) -> _SSTWallDistanceCacheKey:
        """Validate counted geometry and return its exact device-value identity."""

        marker_total = _validated_count(
            marker_count,
            name="marker_count",
            allow_zero=True,
        )
        segment_total = _validated_count(
            projection_segment_count,
            name="projection_segment_count",
            allow_zero=True,
        )
        marker_capacity = 0
        if marker_position_m is not None:
            marker_capacity = _vector_field_capacity(
                marker_position_m,
                name="marker_position_m",
            )
        if marker_total > marker_capacity:
            raise ValueError(
                "marker_count exceeds marker_position_m capacity: "
                f"count={marker_total}, capacity={marker_capacity}"
            )
        if (marker_total > 0 or segment_total > 0) and marker_position_m is None:
            raise ValueError(
                "marker_position_m is required for active SST wall geometry"
            )

        segment_endpoints = np.empty((0, 2), dtype=np.int64)
        if segment_total > 0:
            if projection_segment_indices is None:
                raise ValueError(
                    "projection_segment_indices is required when "
                    "projection_segment_count is positive"
                )
            segment_capacity = _vector_field_capacity(
                projection_segment_indices,
                name="projection_segment_indices",
            )
            if segment_total > segment_capacity:
                raise ValueError(
                    "projection_segment_count exceeds segment field capacity: "
                    f"count={segment_total}, capacity={segment_capacity}"
                )
            raw_segments = _field_numpy(
                projection_segment_indices,
                name="projection_segment_indices",
            )
            if raw_segments.shape != (segment_capacity, 3) or not np.issubdtype(
                raw_segments.dtype,
                np.integer,
            ):
                raise TypeError(
                    "projection_segment_indices must contain integer 3-vectors"
                )
            segment_endpoints = np.asarray(
                raw_segments[:segment_total, :2],
                dtype=np.int64,
            )
            if np.any(segment_endpoints < 0) or np.any(
                segment_endpoints >= marker_capacity
            ):
                raise ValueError(
                    "projection segment endpoint is outside marker_position_m "
                    f"capacity {marker_capacity}"
                )

        marker_digest = ""
        if marker_total > 0 or segment_total > 0:
            raw_positions = _field_numpy(
                marker_position_m,
                name="marker_position_m",
            )
            if raw_positions.shape != (marker_capacity, 3):
                raise TypeError("marker_position_m must contain 3-vectors")
            used_indices = np.arange(marker_total, dtype=np.int64)
            if segment_total > 0:
                used_indices = np.unique(
                    np.concatenate((used_indices, segment_endpoints.reshape(-1)))
                )
            used_positions = np.asarray(raw_positions[used_indices])
            try:
                finite_positions = bool(np.all(np.isfinite(used_positions)))
            except TypeError as exc:
                raise ValueError(
                    "marker_position_m must contain finite numeric values"
                ) from exc
            if not finite_positions:
                raise ValueError("marker_position_m contains a non-finite endpoint")
            marker_digest = _strict_array_digest(used_indices, used_positions)

        return _SSTWallDistanceCacheKey(
            wall_flags=wall_flags,
            obstacle_topology_revision=int(
                self.hibm_external_obstacle_topology_revision
            ),
            inactive_axis=int(inactive_axis),
            marker_count=marker_total,
            segment_count=segment_total,
            marker_digest=marker_digest,
            segment_digest=_strict_array_digest(segment_endpoints),
        )

    def prepare_sst_wall_distance(
        self,
        *,
        no_slip_domain_walls: tuple[bool, bool, bool, bool, bool, bool] | None = None,
        marker_position_m=None,
        marker_count: int = 0,
        projection_segment_indices=None,
        projection_segment_count: int = 0,
        inactive_axis: int | None = None,
    ) -> None:
        """Build a physical wall-distance field on the device.

        Domain faces use their exact physical coordinates.  Cell obstacles
        seed their shared faces.  When no continuous surface is available, a
        device Jacobi distance sweep propagates those voxel distances through
        graded grids.  Sharp-interface callers may instead provide marker
        positions and continuous projection-segment topology;
        an inactive extrusion axis can be removed from that point-to-surface
        distance without a host field round-trip.  Point-cloud distance is a
        compatibility fallback for surfaces without connectivity.
        """

        wall_flags = (
            self._sst_no_slip_domain_walls
            if no_slip_domain_walls is None
            else tuple(bool(flag) for flag in no_slip_domain_walls)
        )
        if len(wall_flags) != 6:
            raise ValueError("no_slip_domain_walls must contain six booleans")
        resolved_inactive_axis = -1 if inactive_axis is None else int(inactive_axis)
        if resolved_inactive_axis not in (-1, 0, 1, 2):
            raise ValueError("inactive_axis must be None, 0, 1, or 2")
        cache_key = self._sst_wall_distance_input_identity(
            wall_flags=wall_flags,
            marker_position_m=marker_position_m,
            marker_count=marker_count,
            projection_segment_indices=projection_segment_indices,
            projection_segment_count=projection_segment_count,
            inactive_axis=resolved_inactive_axis,
        )
        marker_total = cache_key.marker_count
        segment_total = cache_key.segment_count
        propagate_obstacle_distance = (
            marker_total == 0 and segment_total == 0
        )
        if self._sst_wall_distance_valid and cache_key == (
            self._sst_wall_distance_cache_key
        ):
            return
        base_cache_key = _SSTWallDistanceBaseCacheKey(
            wall_flags=wall_flags,
            obstacle_topology_revision=int(
                self.hibm_external_obstacle_topology_revision
            ),
            propagate_obstacle_distance=propagate_obstacle_distance,
        )
        # A failed rebuild must not leave the previous field published under
        # a new geometry identity.
        self._sst_wall_distance_valid = False
        self._sst_wall_distance_cache_key = None
        if base_cache_key == self._sst_wall_distance_base_cache_key:
            self._restore_sst_base_wall_distance_kernel()
        else:
            self._sst_wall_distance_base_cache_key = None
            # A very distant wall gives the intended free-stream F1 -> 0 limit.
            # The previous domain-diagonal fallback spuriously activated the
            # near-wall branch even when no physical wall existed.
            fallback_distance_m = 1.0e20
            self._initialize_sst_wall_distance_kernel(
                *(1 if flag else 0 for flag in wall_flags),
                float(fallback_distance_m),
            )
            if propagate_obstacle_distance and int(self.reduction_count[None]) > 0:
                # JFA provides the fast initial candidate field.  Unit sweeps
                # then run to a device-reported fixed point.
                jump = 1
                maximum_extent = max(self.nx, self.ny, self.nz)
                while jump < maximum_extent:
                    jump *= 2
                while jump >= 1:
                    self._relax_sst_wall_distance_kernel(int(jump))
                    self._commit_sst_wall_distance_kernel()
                    jump //= 2
                for _ in range(maximum_extent):
                    self._relax_sst_wall_distance_kernel(1)
                    self._commit_sst_wall_distance_kernel()
                    if int(self.reduction_count[None]) == 0:
                        break
                else:
                    raise RuntimeError(
                        "SST obstacle wall-distance propagation did not converge"
                    )
            self._sst_wall_distance_base_cache_key = base_cache_key
        # Connectivity is authoritative when supplied: every segment already
        # contains its endpoints, so a separate O(cells * markers) point pass
        # is mathematically redundant and would double long-run wall-distance
        # cost.  Point distance remains the fallback for topology-free callers.
        if marker_total > 0 and segment_total == 0:
            self._include_sst_marker_wall_distance_kernel(
                marker_position_m,
                marker_total,
                resolved_inactive_axis,
            )
        if segment_total > 0:
            self._include_sst_projection_segment_wall_distance_kernel(
                marker_position_m,
                projection_segment_indices,
                segment_total,
                resolved_inactive_axis,
            )
        self._sst_no_slip_domain_walls = wall_flags
        self.sst_no_slip_domain_wall_mask[None] = sum(
            (1 << face) for face, active in enumerate(wall_flags) if active
        )
        self._sst_wall_distance_cache_key = cache_key
        self._sst_wall_distance_valid = True

    def configure_sst_2003(
        self,
        *,
        inlet_velocity_mps: float,
        turbulence_intensity: float,
        turbulent_viscosity_ratio: float,
        inlet_face: str = "zmax",
        outlet_face: str = "zmin",
        no_slip_domain_walls: tuple[bool, bool, bool, bool, bool, bool] | None = None,
        near_wall_treatment: str = "resolved",
        backflow_turbulence_intensity: float | None = None,
        backflow_turbulent_viscosity_ratio: float | None = None,
        max_automatic_substeps: int = 4096,
        defer_wall_distance: bool = False,
    ) -> None:
        """Enable SST-2003 from physical inlet/backflow turbulence data."""

        if not isinstance(defer_wall_distance, (bool, np.bool_)):
            raise TypeError("defer_wall_distance must be bool")
        inlet_speed = float(inlet_velocity_mps)
        intensity = float(turbulence_intensity)
        viscosity_ratio = float(turbulent_viscosity_ratio)
        if not math.isfinite(inlet_speed) or inlet_speed <= 0.0:
            raise ValueError("inlet_velocity_mps must be positive and finite")
        if not math.isfinite(intensity) or not 0.0 < intensity <= 1.0:
            raise ValueError("turbulence_intensity must be in (0, 1]")
        if not math.isfinite(viscosity_ratio) or viscosity_ratio <= 0.0:
            raise ValueError("turbulent_viscosity_ratio must be positive and finite")
        if self.mu <= 0.0:
            raise ValueError("SST-2003 requires positive molecular viscosity")
        normalized_near_wall_treatment = str(near_wall_treatment).strip().lower()
        if normalized_near_wall_treatment not in ("resolved", "fluent_correlation"):
            raise ValueError(
                "near_wall_treatment must be 'resolved' or 'fluent_correlation'"
            )
        substep_limit = int(max_automatic_substeps)
        if substep_limit <= 0:
            raise ValueError("max_automatic_substeps must be positive")
        backflow_intensity = (
            intensity
            if backflow_turbulence_intensity is None
            else float(backflow_turbulence_intensity)
        )
        backflow_ratio = (
            viscosity_ratio
            if backflow_turbulent_viscosity_ratio is None
            else float(backflow_turbulent_viscosity_ratio)
        )
        if not math.isfinite(backflow_intensity) or not 0.0 < backflow_intensity <= 1.0:
            raise ValueError("backflow_turbulence_intensity must be in (0, 1]")
        if not math.isfinite(backflow_ratio) or backflow_ratio <= 0.0:
            raise ValueError(
                "backflow_turbulent_viscosity_ratio must be positive and finite"
            )
        wall_flags = (
            (False, False, False, False, False, False)
            if no_slip_domain_walls is None
            else tuple(bool(flag) for flag in no_slip_domain_walls)
        )
        if len(wall_flags) != 6:
            raise ValueError("no_slip_domain_walls must contain six booleans")
        face_codes = {
            "xmin": self.EXTERNAL_FACE_XMIN,
            "xmax": self.EXTERNAL_FACE_XMAX,
            "ymin": self.EXTERNAL_FACE_YMIN,
            "ymax": self.EXTERNAL_FACE_YMAX,
            "zmin": self.EXTERNAL_FACE_ZMIN,
            "zmax": self.EXTERNAL_FACE_ZMAX,
        }
        normalized_inlet_face = str(inlet_face).strip().lower()
        normalized_outlet_face = str(outlet_face).strip().lower()
        if normalized_inlet_face not in face_codes:
            raise ValueError("inlet_face must name one of xmin/xmax/ymin/ymax/zmin/zmax")
        if normalized_outlet_face not in face_codes:
            raise ValueError("outlet_face must name one of xmin/xmax/ymin/ymax/zmin/zmax")
        if normalized_inlet_face == normalized_outlet_face:
            raise ValueError("inlet_face and outlet_face must be different")
        inlet_face_code = int(face_codes[normalized_inlet_face])
        outlet_face_code = int(face_codes[normalized_outlet_face])
        if wall_flags[inlet_face_code] or wall_flags[outlet_face_code]:
            raise ValueError("SST inlet/outlet faces cannot also be no-slip walls")

        inlet_k = 1.5 * (inlet_speed * intensity) ** 2
        inlet_mu_t = self.mu * viscosity_ratio
        inlet_omega = self.rho * inlet_k / inlet_mu_t
        backflow_k = 1.5 * (inlet_speed * backflow_intensity) ** 2
        backflow_omega = self.rho * backflow_k / (self.mu * backflow_ratio)
        self._initialize_uniform_sst_state_kernel(
            float(inlet_k),
            float(inlet_omega),
            float(inlet_mu_t),
        )
        self._sst_inlet_turbulent_kinetic_energy_m2_s2 = float(inlet_k)
        self._sst_inlet_specific_dissipation_rate_s = float(inlet_omega)
        self._sst_backflow_turbulent_kinetic_energy_m2_s2 = float(backflow_k)
        self._sst_backflow_specific_dissipation_rate_s = float(backflow_omega)
        self._sst_inlet_face_code = inlet_face_code
        self._sst_outlet_face_code = outlet_face_code
        self._sst_max_automatic_substeps = substep_limit
        self._sst_near_wall_treatment = normalized_near_wall_treatment
        self.sst_near_wall_correlation_enabled[None] = (
            1 if normalized_near_wall_treatment == "fluent_correlation" else 0
        )
        if bool(defer_wall_distance):
            # Sharp HIBM marker/segment geometry is created after the fluid
            # object.  Building now would solve a provisional obstacle-only
            # field that the first transport step must immediately discard.
            self._sst_no_slip_domain_walls = wall_flags
            self.sst_no_slip_domain_wall_mask[None] = sum(
                (1 << face) for face, active in enumerate(wall_flags) if active
            )
            self._sst_wall_distance_valid = False
            self._sst_wall_distance_cache_key = None
        else:
            self.prepare_sst_wall_distance(no_slip_domain_walls=wall_flags)
        self.turbulence_model = "sst_2003"

    @ti.kernel
    def _copy_velocity_to_prev_kernel(self):
        for i, j, k in self.velocity:
            self.velocity_prev[i, j, k] = self.velocity[i, j, k]

    @ti.kernel
    def _copy_velocity_to_transport_base_kernel(self):
        for i, j, k in self.velocity:
            self.velocity_transport_base[i, j, k] = self.velocity[i, j, k]

    @ti.kernel
    def _restore_velocity_from_transport_base_kernel(self):
        for i, j, k in self.velocity:
            self.velocity[i, j, k] = self.velocity_transport_base[i, j, k]

    @ti.func
    def _muscl_minmod3(self, first, centered, second):
        value = 0.0
        if first * centered > 0.0 and first * second > 0.0:
            magnitude = ti.min(
                ti.abs(first), ti.min(ti.abs(centered), ti.abs(second))
            )
            value = magnitude if first > 0.0 else -magnitude
        return value

    @ti.func
    def _muscl_smooth_extremum_from_slopes(
        self,
        backward,
        forward,
        outer_backward,
        outer_forward,
        outer_minus_distance,
        minus_distance,
        plus_distance,
        outer_plus_distance,
        value_scale,
        stencil_span,
    ):
        """Recognize a resolved smooth extremum without relaxing shock limiting."""

        d2_minus = 2.0 * (backward - outer_backward) / (
            outer_minus_distance + minus_distance
        )
        d2_center = 2.0 * (forward - backward) / (
            minus_distance + plus_distance
        )
        d2_plus = 2.0 * (outer_forward - forward) / (
            plus_distance + outer_plus_distance
        )
        minimum_curvature = ti.min(
            ti.abs(d2_minus), ti.min(ti.abs(d2_center), ti.abs(d2_plus))
        )
        maximum_curvature = ti.max(
            ti.abs(d2_minus), ti.max(ti.abs(d2_center), ti.abs(d2_plus))
        )
        curvature_epsilon = (
            64.0
            * 1.1920929e-7
            * ti.max(value_scale, 1.0e-30)
            / ti.max(stencil_span * stencil_span, 1.0e-30)
        )
        coherent_curvature = (
            d2_minus * d2_center > 0.0
            and d2_center * d2_plus > 0.0
            and minimum_curvature >= 0.25 * maximum_curvature
        )
        local_spacing = ti.max(
            outer_minus_distance,
            ti.max(
                minus_distance,
                ti.max(plus_distance, outer_plus_distance),
            ),
        )
        resolved_curvature = (
            maximum_curvature * local_spacing * local_spacing
            <= 0.10 * ti.max(value_scale, 1.0e-30)
        )
        smooth = 0.0
        limited_slope = 0.0
        extension_slope = 0.0
        if (
            backward * forward <= 0.0
            and maximum_curvature > curvature_epsilon
            and coherent_curvature
            and resolved_curvature
        ):
            d2_limited_magnitude = ti.min(
                ti.abs(d2_center),
                ti.min(1.25 * ti.abs(d2_minus), 1.25 * ti.abs(d2_plus)),
            )
            d2_limited = (
                d2_limited_magnitude if d2_center > 0.0 else -d2_limited_magnitude
            )
            centered = (
                plus_distance * backward + minus_distance * forward
            ) / (minus_distance + plus_distance)
            extension_slope = (
                1.25 * ti.abs(d2_limited) * ti.max(minus_distance, plus_distance)
            )
            limited_slope = ti.min(
                ti.max(centered, -extension_slope), extension_slope
            )
            smooth = 1.0
        return ti.Vector([smooth, limited_slope, extension_slope])

    @ti.func
    def _muscl_axis_neighbor_is_open(
        self,
        i,
        j,
        k,
        axis: ti.template(),
        side: ti.template(),
    ):
        """Return whether one cell neighbour is connected for reconstruction."""

        neighbor_is_open = 0
        if ti.static(axis == 0):
            if ti.static(side < 0):
                if i > 0:
                    if (
                        self.obstacle[i - 1, j, k] == 0
                        and self._canonical_hibm_exact_component_owner(i, j, k, 0) == 0
                    ):
                        neighbor_is_open = 1
            else:
                if i + 1 < self.nx:
                    if (
                        self.obstacle[i + 1, j, k] == 0
                        and self._canonical_hibm_exact_component_owner(i + 1, j, k, 0) == 0
                    ):
                        neighbor_is_open = 1
        elif ti.static(axis == 1):
            if ti.static(side < 0):
                if j > 0:
                    if (
                        self.obstacle[i, j - 1, k] == 0
                        and self._canonical_hibm_exact_component_owner(i, j, k, 1) == 0
                    ):
                        neighbor_is_open = 1
            else:
                if j + 1 < self.ny:
                    if (
                        self.obstacle[i, j + 1, k] == 0
                        and self._canonical_hibm_exact_component_owner(i, j + 1, k, 1) == 0
                    ):
                        neighbor_is_open = 1
        else:
            if ti.static(side < 0):
                if k > 0:
                    if (
                        self.obstacle[i, j, k - 1] == 0
                        and self._canonical_hibm_exact_component_owner(i, j, k, 2) == 0
                    ):
                        neighbor_is_open = 1
            else:
                if k + 1 < self.nz:
                    if (
                        self.obstacle[i, j, k + 1] == 0
                        and self._canonical_hibm_exact_component_owner(i, j, k + 1, 2) == 0
                    ):
                        neighbor_is_open = 1
        return neighbor_is_open

    @ti.func
    def _muscl_extremum_stencil_is_unconstrained(
        self,
        i,
        j,
        k,
        axis: ti.template(),
        component_mask: ti.template(),
    ):
        unconstrained = 1
        for offset in ti.static(range(-2, 3)):
            ii = i
            jj = j
            kk = k
            if ti.static(axis == 0):
                ii += offset
            elif ti.static(axis == 1):
                jj += offset
            else:
                kk += offset
            if not (0 <= ii < self.nx and 0 <= jj < self.ny and 0 <= kk < self.nz):
                unconstrained = 0
            elif (
                self.velocity_dirichlet_boundary_active[ii, jj, kk] != 0
                or (
                    self.velocity_dirichlet_boundary_active_component_mask[ii, jj, kk]
                    & component_mask
                )
                != 0
            ):
                unconstrained = 0
        # Five sampled cells span four primal faces.  A canonical fluid-fluid
        # wall is not visible in ``obstacle`` and must truncate the stencil at
        # the owned face just like a phase-changing obstacle interface.
        for face_offset in ti.static(range(-1, 3)):
            ii = i
            jj = j
            kk = k
            if ti.static(axis == 0):
                ii += face_offset
            elif ti.static(axis == 1):
                jj += face_offset
            else:
                kk += face_offset
            if 0 <= ii < self.nx and 0 <= jj < self.ny and 0 <= kk < self.nz:
                if (
                    self._canonical_hibm_exact_component_owner(
                        ii, jj, kk, axis
                    )
                    != 0
                ):
                    unconstrained = 0
        return unconstrained

    @ti.func
    def _muscl_scalar_has_smooth_extremum(
        self, field: ti.template(), i, j, k, axis: ti.template()
    ):
        center = field[i, j, k]
        minus = center
        plus = center
        outer_minus = center
        outer_plus = center
        minus_distance = 1.0
        plus_distance = 1.0
        outer_minus_distance = 1.0
        outer_plus_distance = 1.0
        complete_stencil = 0
        if ti.static(axis == 0):
            if (
                i > 1
                and i + 2 < self.nx
                and self.obstacle[i - 2, j, k] == 0
                and self.obstacle[i - 1, j, k] == 0
                and self.obstacle[i + 1, j, k] == 0
                and self.obstacle[i + 2, j, k] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 7
                )
                != 0
            ):
                outer_minus = field[i - 2, j, k]
                minus = field[i - 1, j, k]
                plus = field[i + 1, j, k]
                outer_plus = field[i + 2, j, k]
                outer_minus_distance = self.center_distance_x_m[i - 1]
                minus_distance = self.center_distance_x_m[i]
                plus_distance = self.center_distance_x_m[i + 1]
                outer_plus_distance = self.center_distance_x_m[i + 2]
                complete_stencil = 1
        elif ti.static(axis == 1):
            if (
                j > 1
                and j + 2 < self.ny
                and self.obstacle[i, j - 2, k] == 0
                and self.obstacle[i, j - 1, k] == 0
                and self.obstacle[i, j + 1, k] == 0
                and self.obstacle[i, j + 2, k] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 7
                )
                != 0
            ):
                outer_minus = field[i, j - 2, k]
                minus = field[i, j - 1, k]
                plus = field[i, j + 1, k]
                outer_plus = field[i, j + 2, k]
                outer_minus_distance = self.center_distance_y_m[j - 1]
                minus_distance = self.center_distance_y_m[j]
                plus_distance = self.center_distance_y_m[j + 1]
                outer_plus_distance = self.center_distance_y_m[j + 2]
                complete_stencil = 1
        else:
            if (
                k > 1
                and k + 2 < self.nz
                and self.obstacle[i, j, k - 2] == 0
                and self.obstacle[i, j, k - 1] == 0
                and self.obstacle[i, j, k + 1] == 0
                and self.obstacle[i, j, k + 2] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 7
                )
                != 0
            ):
                outer_minus = field[i, j, k - 2]
                minus = field[i, j, k - 1]
                plus = field[i, j, k + 1]
                outer_plus = field[i, j, k + 2]
                outer_minus_distance = self.center_distance_z_m[k - 1]
                minus_distance = self.center_distance_z_m[k]
                plus_distance = self.center_distance_z_m[k + 1]
                outer_plus_distance = self.center_distance_z_m[k + 2]
                complete_stencil = 1
        smooth_info = ti.Vector([0.0, 0.0, 0.0])
        if complete_stencil != 0:
            backward = (center - minus) / minus_distance
            forward = (plus - center) / plus_distance
            outer_backward = (minus - outer_minus) / outer_minus_distance
            outer_forward = (outer_plus - plus) / outer_plus_distance
            value_scale = ti.max(
                ti.abs(center),
                ti.max(
                    ti.abs(minus),
                    ti.max(
                        ti.abs(plus),
                        ti.max(ti.abs(outer_minus), ti.abs(outer_plus)),
                    ),
                ),
            )
            smooth_info = self._muscl_smooth_extremum_from_slopes(
                backward,
                forward,
                outer_backward,
                outer_forward,
                outer_minus_distance,
                minus_distance,
                plus_distance,
                outer_plus_distance,
                value_scale,
                outer_minus_distance
                + minus_distance
                + plus_distance
                + outer_plus_distance,
            )
        return smooth_info

    @ti.func
    def _muscl_vector_component_has_smooth_extremum(
        self,
        field: ti.template(),
        i,
        j,
        k,
        axis: ti.template(),
        component: ti.template(),
    ):
        center = field[i, j, k][component]
        minus = center
        plus = center
        outer_minus = center
        outer_plus = center
        minus_distance = 1.0
        plus_distance = 1.0
        outer_minus_distance = 1.0
        outer_plus_distance = 1.0
        complete_stencil = 0
        if ti.static(axis == 0):
            if (
                i > 1
                and i + 2 < self.nx
                and self.obstacle[i - 2, j, k] == 0
                and self.obstacle[i - 1, j, k] == 0
                and self.obstacle[i + 1, j, k] == 0
                and self.obstacle[i + 2, j, k] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 1 << component
                )
                != 0
            ):
                outer_minus = field[i - 2, j, k][component]
                minus = field[i - 1, j, k][component]
                plus = field[i + 1, j, k][component]
                outer_plus = field[i + 2, j, k][component]
                if ti.static(component == 0):
                    outer_minus_distance = self.cell_width_x_m[i - 2]
                    minus_distance = self.cell_width_x_m[i - 1]
                    plus_distance = self.cell_width_x_m[i]
                    outer_plus_distance = self.cell_width_x_m[i + 1]
                else:
                    outer_minus_distance = self.center_distance_x_m[i - 1]
                    minus_distance = self.center_distance_x_m[i]
                    plus_distance = self.center_distance_x_m[i + 1]
                    outer_plus_distance = self.center_distance_x_m[i + 2]
                complete_stencil = 1
        elif ti.static(axis == 1):
            if (
                j > 1
                and j + 2 < self.ny
                and self.obstacle[i, j - 2, k] == 0
                and self.obstacle[i, j - 1, k] == 0
                and self.obstacle[i, j + 1, k] == 0
                and self.obstacle[i, j + 2, k] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 1 << component
                )
                != 0
            ):
                outer_minus = field[i, j - 2, k][component]
                minus = field[i, j - 1, k][component]
                plus = field[i, j + 1, k][component]
                outer_plus = field[i, j + 2, k][component]
                if ti.static(component == 1):
                    outer_minus_distance = self.cell_width_y_m[j - 2]
                    minus_distance = self.cell_width_y_m[j - 1]
                    plus_distance = self.cell_width_y_m[j]
                    outer_plus_distance = self.cell_width_y_m[j + 1]
                else:
                    outer_minus_distance = self.center_distance_y_m[j - 1]
                    minus_distance = self.center_distance_y_m[j]
                    plus_distance = self.center_distance_y_m[j + 1]
                    outer_plus_distance = self.center_distance_y_m[j + 2]
                complete_stencil = 1
        else:
            if (
                k > 1
                and k + 2 < self.nz
                and self.obstacle[i, j, k - 2] == 0
                and self.obstacle[i, j, k - 1] == 0
                and self.obstacle[i, j, k + 1] == 0
                and self.obstacle[i, j, k + 2] == 0
                and self._muscl_extremum_stencil_is_unconstrained(
                    i, j, k, axis, 1 << component
                )
                != 0
            ):
                outer_minus = field[i, j, k - 2][component]
                minus = field[i, j, k - 1][component]
                plus = field[i, j, k + 1][component]
                outer_plus = field[i, j, k + 2][component]
                if ti.static(component == 2):
                    outer_minus_distance = self.cell_width_z_m[k - 2]
                    minus_distance = self.cell_width_z_m[k - 1]
                    plus_distance = self.cell_width_z_m[k]
                    outer_plus_distance = self.cell_width_z_m[k + 1]
                else:
                    outer_minus_distance = self.center_distance_z_m[k - 1]
                    minus_distance = self.center_distance_z_m[k]
                    plus_distance = self.center_distance_z_m[k + 1]
                    outer_plus_distance = self.center_distance_z_m[k + 2]
                complete_stencil = 1
        smooth_info = ti.Vector([0.0, 0.0, 0.0])
        if complete_stencil != 0:
            backward = (center - minus) / minus_distance
            forward = (plus - center) / plus_distance
            outer_backward = (minus - outer_minus) / outer_minus_distance
            outer_forward = (outer_plus - plus) / outer_plus_distance
            value_scale = ti.max(
                ti.abs(center),
                ti.max(
                    ti.abs(minus),
                    ti.max(
                        ti.abs(plus),
                        ti.max(ti.abs(outer_minus), ti.abs(outer_plus)),
                    ),
                ),
            )
            smooth_info = self._muscl_smooth_extremum_from_slopes(
                backward,
                forward,
                outer_backward,
                outer_forward,
                outer_minus_distance,
                minus_distance,
                plus_distance,
                outer_plus_distance,
                value_scale,
                outer_minus_distance
                + minus_distance
                + plus_distance
                + outer_plus_distance,
            )
        return smooth_info

    @ti.func
    def _muscl_vector_component_slope(
        self, field: ti.template(), i, j, k, axis: ti.template(), component: ti.template()
    ):
        center = field[i, j, k][component]
        minus = center
        plus = center
        minus_distance = 1.0
        plus_distance = 1.0
        complete = 0
        if ti.static(axis == 0):
            if (
                i > 0
                and i + 1 < self.nx
                and self.obstacle[i - 1, j, k] == 0
                and self.obstacle[i + 1, j, k] == 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0
            ):
                minus = field[i - 1, j, k][component]
                plus = field[i + 1, j, k][component]
                if ti.static(component == 0):
                    minus_distance = self.cell_width_x_m[i - 1]
                    plus_distance = self.cell_width_x_m[i]
                else:
                    minus_distance = self.center_distance_x_m[i]
                    plus_distance = self.center_distance_x_m[i + 1]
                complete = 1
        elif ti.static(axis == 1):
            if (
                j > 0
                and j + 1 < self.ny
                and self.obstacle[i, j - 1, k] == 0
                and self.obstacle[i, j + 1, k] == 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0
            ):
                minus = field[i, j - 1, k][component]
                plus = field[i, j + 1, k][component]
                if ti.static(component == 1):
                    minus_distance = self.cell_width_y_m[j - 1]
                    plus_distance = self.cell_width_y_m[j]
                else:
                    minus_distance = self.center_distance_y_m[j]
                    plus_distance = self.center_distance_y_m[j + 1]
                complete = 1
        else:
            if (
                k > 0
                and k + 1 < self.nz
                and self.obstacle[i, j, k - 1] == 0
                and self.obstacle[i, j, k + 1] == 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0
                and self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0
            ):
                minus = field[i, j, k - 1][component]
                plus = field[i, j, k + 1][component]
                if ti.static(component == 2):
                    minus_distance = self.cell_width_z_m[k - 1]
                    plus_distance = self.cell_width_z_m[k]
                else:
                    minus_distance = self.center_distance_z_m[k]
                    plus_distance = self.center_distance_z_m[k + 1]
                complete = 1
        slope = 0.0
        if complete != 0:
            backward = (center - minus) / minus_distance
            forward = (plus - center) / plus_distance
            centered = (
                plus_distance * backward + minus_distance * forward
            ) / (minus_distance + plus_distance)
            slope = self._muscl_minmod3(
                2.0 * backward, centered, 2.0 * forward
            )
        return slope

    @ti.kernel
    def _prepare_muscl_velocity_axis_reconstruction_kernel(
        self,
        field: ti.template(),
        axis: ti.template(),
    ):
        for i, j, k in field:
            for component in ti.static(range(3)):
                slope = 0.0
                extension = 0.0
                smooth = 0
                if self.obstacle[i, j, k] == 0:
                    slope = self._muscl_vector_component_slope(
                        field, i, j, k, axis, component
                    )
                    smooth_info = (
                        self._muscl_vector_component_has_smooth_extremum(
                            field, i, j, k, axis, component
                        )
                    )
                    if smooth_info[0] != 0.0:
                        slope = smooth_info[1]
                        extension = smooth_info[2]
                        smooth = 1
                self.muscl_velocity_slope[i, j, k][axis, component] = slope
                self.muscl_velocity_smooth_mask[i, j, k][axis, component] = smooth
                self.muscl_velocity_extension_slope[i, j, k][
                    axis, component
                ] = extension

    @ti.func
    def _muscl_scalar_slope(
        self, field: ti.template(), i, j, k, axis: ti.template()
    ):
        center = field[i, j, k]
        minus = center
        plus = center
        minus_distance = 1.0
        plus_distance = 1.0
        minus_valid = 0
        plus_valid = 0
        if ti.static(axis == 0):
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0:
                minus = field[i - 1, j, k]
                minus_distance = self.center_distance_x_m[i]
                minus_valid = 1
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0:
                plus = field[i + 1, j, k]
                plus_distance = self.center_distance_x_m[i + 1]
                plus_valid = 1
        elif ti.static(axis == 1):
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0:
                minus = field[i, j - 1, k]
                minus_distance = self.center_distance_y_m[j]
                minus_valid = 1
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0:
                plus = field[i, j + 1, k]
                plus_distance = self.center_distance_y_m[j + 1]
                plus_valid = 1
        else:
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, -1) != 0:
                minus = field[i, j, k - 1]
                minus_distance = self.center_distance_z_m[k]
                minus_valid = 1
            if self._muscl_axis_neighbor_is_open(i, j, k, axis, 1) != 0:
                plus = field[i, j, k + 1]
                plus_distance = self.center_distance_z_m[k + 1]
                plus_valid = 1

        slope = 0.0
        backward = (center - minus) / minus_distance
        forward = (plus - center) / plus_distance
        if minus_valid != 0 and plus_valid != 0:
            centered = (
                plus_distance * backward + minus_distance * forward
            ) / (minus_distance + plus_distance)
            slope = self._muscl_minmod3(2.0 * backward, centered, 2.0 * forward)
        return slope

    @ti.kernel
    def _prepare_muscl_scalar_axis_reconstruction_kernel(
        self,
        field: ti.template(),
        slope_field: ti.template(),
        smooth_mask_field: ti.template(),
        extension_field: ti.template(),
        axis: ti.template(),
    ):
        for i, j, k in field:
            slope = 0.0
            extension = 0.0
            smooth = 0
            if self.obstacle[i, j, k] == 0:
                slope = self._muscl_scalar_slope(field, i, j, k, axis)
                smooth_info = self._muscl_scalar_has_smooth_extremum(
                    field, i, j, k, axis
                )
                if smooth_info[0] != 0.0:
                    slope = smooth_info[1]
                    extension = smooth_info[2]
                    smooth = 1
            slope_field[i, j, k][axis] = slope
            smooth_mask_field[i, j, k][axis] = smooth
            extension_field[i, j, k][axis] = extension

    @ti.func
    def _muscl_vector_face_state(
        self,
        field: ti.template(),
        i,
        j,
        k,
        axis: ti.template(),
        side: ti.template(),
    ):
        center = field[i, j, k]
        neighbor = center
        neighbor_valid = 0
        if ti.static(axis == 0):
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i - 1, j, k]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i + 1, j, k]
                    neighbor_valid = 1
        elif ti.static(axis == 1):
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j - 1, k]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j + 1, k]
                    neighbor_valid = 1
        else:
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j, k - 1]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j, k + 1]
                    neighbor_valid = 1
        value = center
        for component in ti.static(range(3)):
            # Packed backward-MAC components do not share one collocated
            # reconstruction coordinate.  The component normal to ``axis``
            # lives at F_axis and reconstructs to the adjacent scalar centres
            # (the faces of its dual control volume).  Transverse components
            # live at C_axis and reconstruct to the primal scalar faces.
            face_position = 0.0
            center_position = 0.0
            if ti.static(axis == 0):
                if ti.static(component == 0):
                    center_position = self.cell_face_x_m[i]
                    face_position = (
                        self.cell_face_x_m[0]
                        if side < 0 and i == 0
                        else self.cell_center_x_m[i - 1 if side < 0 else i]
                    )
                else:
                    center_position = self.cell_center_x_m[i]
                    face_position = self.cell_face_x_m[i if side < 0 else i + 1]
            elif ti.static(axis == 1):
                if ti.static(component == 1):
                    center_position = self.cell_face_y_m[j]
                    face_position = (
                        self.cell_face_y_m[0]
                        if side < 0 and j == 0
                        else self.cell_center_y_m[j - 1 if side < 0 else j]
                    )
                else:
                    center_position = self.cell_center_y_m[j]
                    face_position = self.cell_face_y_m[j if side < 0 else j + 1]
            else:
                if ti.static(component == 2):
                    center_position = self.cell_face_z_m[k]
                    face_position = (
                        self.cell_face_z_m[0]
                        if side < 0 and k == 0
                        else self.cell_center_z_m[k - 1 if side < 0 else k]
                    )
                else:
                    center_position = self.cell_center_z_m[k]
                    face_position = self.cell_face_z_m[k if side < 0 else k + 1]
            distance = face_position - center_position
            value[component] = center[component] + (
                self.muscl_velocity_slope[i, j, k][axis, component] * distance
            )
            if neighbor_valid != 0:
                smooth = self.muscl_velocity_smooth_mask[i, j, k][
                    axis, component
                ] != 0
                if not smooth:
                    value[component] = ti.min(
                        ti.max(
                            value[component],
                            ti.min(center[component], neighbor[component]),
                        ),
                        ti.max(center[component], neighbor[component]),
                    )
                else:
                    extension = (
                        self.muscl_velocity_extension_slope[i, j, k][axis, component]
                        * ti.abs(distance)
                    )
                    value[component] = ti.min(
                        ti.max(
                            value[component],
                            ti.min(center[component], neighbor[component]) - extension,
                        ),
                        ti.max(center[component], neighbor[component]) + extension,
                    )
        return value

    @ti.func
    def _muscl_scalar_face_state(
        self,
        field: ti.template(),
        slope_field: ti.template(),
        smooth_mask_field: ti.template(),
        extension_field: ti.template(),
        i,
        j,
        k,
        axis: ti.template(),
        side: ti.template(),
    ):
        center = field[i, j, k]
        face_position = 0.0
        center_position = 0.0
        neighbor = center
        neighbor_valid = 0
        if ti.static(axis == 0):
            face_position = self.cell_face_x_m[i if side < 0 else i + 1]
            center_position = self.cell_center_x_m[i]
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i - 1, j, k]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i + 1, j, k]
                    neighbor_valid = 1
        elif ti.static(axis == 1):
            face_position = self.cell_face_y_m[j if side < 0 else j + 1]
            center_position = self.cell_center_y_m[j]
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j - 1, k]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j + 1, k]
                    neighbor_valid = 1
        else:
            face_position = self.cell_face_z_m[k if side < 0 else k + 1]
            center_position = self.cell_center_z_m[k]
            if ti.static(side < 0):
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j, k - 1]
                    neighbor_valid = 1
            else:
                if self._muscl_axis_neighbor_is_open(i, j, k, axis, side) != 0:
                    neighbor = field[i, j, k + 1]
                    neighbor_valid = 1
        value = center + slope_field[i, j, k][axis] * (
            face_position - center_position
        )
        if neighbor_valid != 0:
            if smooth_mask_field[i, j, k][axis] == 0:
                value = ti.min(
                    ti.max(value, ti.min(center, neighbor)), ti.max(center, neighbor)
                )
            else:
                extension = extension_field[i, j, k][axis] * ti.abs(
                    face_position - center_position
                )
                value = ti.min(
                    ti.max(value, ti.min(center, neighbor) - extension),
                    ti.max(center, neighbor) + extension,
                )
        return value

    @ti.func
    def _muscl_sst_k_face_state(
        self, i, j, k, axis: ti.template(), side: ti.template()
    ):
        return self._muscl_scalar_face_state(
            self.sst_turbulent_kinetic_energy_prev,
            self.muscl_sst_k_slope,
            self.muscl_sst_k_smooth_mask,
            self.muscl_sst_k_extension_slope,
            i,
            j,
            k,
            axis,
            side,
        )

    @ti.func
    def _muscl_sst_omega_face_state(
        self, i, j, k, axis: ti.template(), side: ti.template()
    ):
        return self._muscl_scalar_face_state(
            self.sst_specific_dissipation_rate_prev,
            self.muscl_sst_omega_slope,
            self.muscl_sst_omega_smooth_mask,
            self.muscl_sst_omega_extension_slope,
            i,
            j,
            k,
            axis,
            side,
        )

    @ti.kernel
    def _synchronize_muscl_minimum_normal_boundary_rows_kernel(
        self,
        source: ti.template(),
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        """Make the colocated minimum-side MAC normals match physical faces.

        A compact backward-MAC row owns three different faces.  Only row0's
        component normal to a minimum domain side is colocated with that
        physical face; the two tangential components must remain untouched.
        Use the same exterior contract as Q, including default closure and
        the explicit pressure-correctable zmin row.  No maximum-side packed
        row is modified: those rows own internal faces.
        """

        for i, j, k in source:
            value = source[i, j, k]
            if self.obstacle[i, j, k] == 0:
                if i == 0:
                    value.x = self._physical_exterior_normal_velocity(
                        source, 0, 0, i, j, k,
                        pressure_outlet_zmin, velocity_inlet_zmax_mode,
                    )
                if j == 0:
                    value.y = self._physical_exterior_normal_velocity(
                        source, 1, 0, i, j, k,
                        pressure_outlet_zmin, velocity_inlet_zmax_mode,
                    )
                if k == 0:
                    value.z = self._physical_exterior_normal_velocity(
                        source, 2, 0, i, j, k,
                        pressure_outlet_zmin, velocity_inlet_zmax_mode,
                    )
            source[i, j, k] = value

    @ti.kernel
    def _compute_muscl_momentum_dual_geometry_kernel(self):
        for i, j, k in self.velocity:
            for component in ti.static(range(3)):
                minus_fluid = 0
                plus_fluid = 0
                minus_width = 0.0
                plus_width = 0.0
                transverse_area = 0.0
                if ti.static(component == 0):
                    if i > 0:
                        minus_fluid = 1 if self.obstacle[i - 1, j, k] == 0 else 0
                        minus_width = 0.5 * self.cell_width_x_m[i - 1]
                    plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                    plus_width = 0.5 * self.cell_width_x_m[i]
                    transverse_area = (
                        self.cell_width_y_m[j] * self.cell_width_z_m[k]
                    )
                elif ti.static(component == 1):
                    if j > 0:
                        minus_fluid = 1 if self.obstacle[i, j - 1, k] == 0 else 0
                        minus_width = 0.5 * self.cell_width_y_m[j - 1]
                    plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                    plus_width = 0.5 * self.cell_width_y_m[j]
                    transverse_area = (
                        self.cell_width_x_m[i] * self.cell_width_z_m[k]
                    )
                else:
                    if k > 0:
                        minus_fluid = 1 if self.obstacle[i, j, k - 1] == 0 else 0
                        minus_width = 0.5 * self.cell_width_z_m[k - 1]
                    plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                    plus_width = 0.5 * self.cell_width_z_m[k]
                    transverse_area = (
                        self.cell_width_x_m[i] * self.cell_width_y_m[j]
                    )

                self.muscl_momentum_dual_volume_m3[i, j, k, component] = (
                    minus_width * ti.cast(minus_fluid, ti.f32)
                    + plus_width * ti.cast(plus_fluid, ti.f32)
                ) * transverse_area

    @ti.kernel
    def _compute_muscl_primal_normal_velocity_x_kernel(
        self,
        source: ti.template(),
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for face, j, k in self.muscl_normal_velocity_x:
            normal_velocity = 0.0
            if face == 0:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 0, 0, 0, j, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.nx:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 0, 1, self.nx - 1, j, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                minus_fluid = self.obstacle[face - 1, j, k] == 0
                plus_fluid = self.obstacle[face, j, k] == 0
                canonical_wall = (
                    self._canonical_hibm_exact_component_owner(
                        face, j, k, 0
                    )
                    != 0
                )
                if minus_fluid and plus_fluid and not canonical_wall:
                    normal_velocity = source[face, j, k].x
                # Any immersed primal face is impermeable in the wall-relative
                # transport ledger.  In particular, never admit a stale raw A
                # or B owner value into Q: an exact moving-wall target also has
                # zero relative normal volume flux.
            self.muscl_normal_velocity_x[face, j, k] = normal_velocity

    @ti.kernel
    def _compute_muscl_primal_normal_velocity_y_kernel(
        self,
        source: ti.template(),
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for i, face, k in self.muscl_normal_velocity_y:
            normal_velocity = 0.0
            if face == 0:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 1, 0, i, 0, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.ny:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 1, 1, i, self.ny - 1, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                minus_fluid = self.obstacle[i, face - 1, k] == 0
                plus_fluid = self.obstacle[i, face, k] == 0
                canonical_wall = (
                    self._canonical_hibm_exact_component_owner(
                        i, face, k, 1
                    )
                    != 0
                )
                if minus_fluid and plus_fluid and not canonical_wall:
                    normal_velocity = source[i, face, k].y
            self.muscl_normal_velocity_y[i, face, k] = normal_velocity

    @ti.kernel
    def _compute_muscl_primal_normal_velocity_z_kernel(
        self,
        source: ti.template(),
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for i, j, face in self.muscl_normal_velocity_z:
            normal_velocity = 0.0
            if face == 0:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 2, 0, i, j, 0,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.nz:
                normal_velocity = self._physical_exterior_normal_velocity(
                    source, 2, 1, i, j, self.nz - 1,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                minus_fluid = self.obstacle[i, j, face - 1] == 0
                plus_fluid = self.obstacle[i, j, face] == 0
                canonical_wall = (
                    self._canonical_hibm_exact_component_owner(
                        i, j, face, 2
                    )
                    != 0
                )
                if minus_fluid and plus_fluid and not canonical_wall:
                    normal_velocity = source[i, j, face].z
            self.muscl_normal_velocity_z[i, j, face] = normal_velocity

    @ti.kernel
    def _compute_muscl_momentum_flux_x_kernel(
        self,
        source: ti.template(),
        no_slip_xmin: ti.i32,
        no_slip_xmax: ti.i32,
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for face, j, k in self.muscl_momentum_flux_x:
            left = ti.Vector([0.0, 0.0, 0.0])
            right = ti.Vector([0.0, 0.0, 0.0])
            if face == 0:
                right = self._muscl_vector_face_state(source, 0, j, k, 0, -1)
                left = right
                if no_slip_xmin != 0:
                    left = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_x_face_active_component_mask[
                    0, j, k
                ]
                target = self.external_velocity_boundary_x_face_value_mps[0, j, k]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        left[component] = target[component]
                left.x = self._physical_exterior_normal_velocity(
                    source, 0, 0, 0, j, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.nx:
                left = self._muscl_vector_face_state(
                    source, self.nx - 1, j, k, 0, 1
                )
                right = left
                if no_slip_xmax != 0:
                    right = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_x_face_active_component_mask[
                    1, j, k
                ]
                target = self.external_velocity_boundary_x_face_value_mps[1, j, k]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        right[component] = target[component]
                right.x = self._physical_exterior_normal_velocity(
                    source, 0, 1, self.nx - 1, j, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                left = self._muscl_vector_face_state(
                    source, face - 1, j, k, 0, 1
                )
                right = self._muscl_vector_face_state(
                    source, face, j, k, 0, -1
                )

            flux = ti.Vector([0.0, 0.0, 0.0])
            for component in ti.static(range(3)):
                q_minus = 0.0
                q_plus = 0.0
                if ti.static(component == 0):
                    area = self.cell_width_y_m[j] * self.cell_width_z_m[k]
                    if face == 0:
                        q_minus = self.muscl_normal_velocity_x[0, j, k] * area
                    elif self.obstacle[face - 1, j, k] == 0:
                        q_minus = 0.5 * area * (
                            self.muscl_normal_velocity_x[face - 1, j, k]
                            + self.muscl_normal_velocity_x[face, j, k]
                        )
                elif ti.static(component == 1):
                    if j > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_y_m[j - 1]
                            * self.cell_width_z_m[k]
                            * self.muscl_normal_velocity_x[face, j - 1, k]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_y_m[j]
                        * self.cell_width_z_m[k]
                        * self.muscl_normal_velocity_x[face, j, k]
                    )
                else:
                    if k > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_z_m[k - 1]
                            * self.cell_width_y_m[j]
                            * self.muscl_normal_velocity_x[face, j, k - 1]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_z_m[k]
                        * self.cell_width_y_m[j]
                        * self.muscl_normal_velocity_x[face, j, k]
                    )
                self.muscl_momentum_volume_flux_x_half_m3_s[
                    face, j, k, component, 0
                ] = q_minus
                self.muscl_momentum_volume_flux_x_half_m3_s[
                    face, j, k, component, 1
                ] = q_plus
                flux[component] = q_minus * (
                    left[component] if q_minus >= 0.0 else right[component]
                ) + q_plus * (
                    left[component] if q_plus >= 0.0 else right[component]
                )
            self.muscl_momentum_flux_x[face, j, k] = flux

    @ti.kernel
    def _compute_muscl_momentum_flux_y_kernel(
        self,
        source: ti.template(),
        no_slip_ymin: ti.i32,
        no_slip_ymax: ti.i32,
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for i, face, k in self.muscl_momentum_flux_y:
            left = ti.Vector([0.0, 0.0, 0.0])
            right = ti.Vector([0.0, 0.0, 0.0])
            if face == 0:
                right = self._muscl_vector_face_state(source, i, 0, k, 1, -1)
                left = right
                if no_slip_ymin != 0:
                    left = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_y_face_active_component_mask[
                    0, i, k
                ]
                target = self.external_velocity_boundary_y_face_value_mps[0, i, k]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        left[component] = target[component]
                left.y = self._physical_exterior_normal_velocity(
                    source, 1, 0, i, 0, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.ny:
                left = self._muscl_vector_face_state(
                    source, i, self.ny - 1, k, 1, 1
                )
                right = left
                if no_slip_ymax != 0:
                    right = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_y_face_active_component_mask[
                    1, i, k
                ]
                target = self.external_velocity_boundary_y_face_value_mps[1, i, k]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        right[component] = target[component]
                right.y = self._physical_exterior_normal_velocity(
                    source, 1, 1, i, self.ny - 1, k,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                left = self._muscl_vector_face_state(
                    source, i, face - 1, k, 1, 1
                )
                right = self._muscl_vector_face_state(
                    source, i, face, k, 1, -1
                )

            flux = ti.Vector([0.0, 0.0, 0.0])
            for component in ti.static(range(3)):
                q_minus = 0.0
                q_plus = 0.0
                if ti.static(component == 0):
                    if i > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_x_m[i - 1]
                            * self.cell_width_z_m[k]
                            * self.muscl_normal_velocity_y[i - 1, face, k]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_x_m[i]
                        * self.cell_width_z_m[k]
                        * self.muscl_normal_velocity_y[i, face, k]
                    )
                elif ti.static(component == 1):
                    area = self.cell_width_x_m[i] * self.cell_width_z_m[k]
                    if face == 0:
                        q_minus = self.muscl_normal_velocity_y[i, 0, k] * area
                    elif self.obstacle[i, face - 1, k] == 0:
                        q_minus = 0.5 * area * (
                            self.muscl_normal_velocity_y[i, face - 1, k]
                            + self.muscl_normal_velocity_y[i, face, k]
                        )
                else:
                    if k > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_z_m[k - 1]
                            * self.cell_width_x_m[i]
                            * self.muscl_normal_velocity_y[i, face, k - 1]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_z_m[k]
                        * self.cell_width_x_m[i]
                        * self.muscl_normal_velocity_y[i, face, k]
                    )
                self.muscl_momentum_volume_flux_y_half_m3_s[
                    i, face, k, component, 0
                ] = q_minus
                self.muscl_momentum_volume_flux_y_half_m3_s[
                    i, face, k, component, 1
                ] = q_plus
                flux[component] = q_minus * (
                    left[component] if q_minus >= 0.0 else right[component]
                ) + q_plus * (
                    left[component] if q_plus >= 0.0 else right[component]
                )
            self.muscl_momentum_flux_y[i, face, k] = flux

    @ti.kernel
    def _compute_muscl_momentum_flux_z_kernel(
        self,
        source: ti.template(),
        no_slip_zmin: ti.i32,
        no_slip_zmax: ti.i32,
        pressure_outlet_zmin: ti.i32,
        velocity_inlet_zmax_mode: ti.i32,
    ):
        for i, j, face in self.muscl_momentum_flux_z:
            left = ti.Vector([0.0, 0.0, 0.0])
            right = ti.Vector([0.0, 0.0, 0.0])
            if face == 0:
                right = self._muscl_vector_face_state(source, i, j, 0, 2, -1)
                left = right
                if no_slip_zmin != 0:
                    left = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_z_face_active_component_mask[
                    0, i, j
                ]
                target = self.external_velocity_boundary_z_face_value_mps[0, i, j]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        left[component] = target[component]
                left.z = self._physical_exterior_normal_velocity(
                    source, 2, 0, i, j, 0,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            elif face == self.nz:
                left = self._muscl_vector_face_state(
                    source, i, j, self.nz - 1, 2, 1
                )
                right = left
                if no_slip_zmax != 0:
                    right = ti.Vector([0.0, 0.0, 0.0])
                mask = self.external_velocity_boundary_z_face_active_component_mask[
                    1, i, j
                ]
                target = self.external_velocity_boundary_z_face_value_mps[1, i, j]
                for component in ti.static(range(3)):
                    if (mask & (1 << component)) != 0:
                        right[component] = target[component]
                right.z = self._physical_exterior_normal_velocity(
                    source, 2, 1, i, j, self.nz - 1,
                    pressure_outlet_zmin, velocity_inlet_zmax_mode,
                )
            else:
                left = self._muscl_vector_face_state(
                    source, i, j, face - 1, 2, 1
                )
                right = self._muscl_vector_face_state(
                    source, i, j, face, 2, -1
                )

            flux = ti.Vector([0.0, 0.0, 0.0])
            for component in ti.static(range(3)):
                q_minus = 0.0
                q_plus = 0.0
                if ti.static(component == 0):
                    if i > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_x_m[i - 1]
                            * self.cell_width_y_m[j]
                            * self.muscl_normal_velocity_z[i - 1, j, face]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_x_m[i]
                        * self.cell_width_y_m[j]
                        * self.muscl_normal_velocity_z[i, j, face]
                    )
                elif ti.static(component == 1):
                    if j > 0:
                        q_minus = (
                            0.5
                            * self.cell_width_y_m[j - 1]
                            * self.cell_width_x_m[i]
                            * self.muscl_normal_velocity_z[i, j - 1, face]
                        )
                    q_plus = (
                        0.5
                        * self.cell_width_y_m[j]
                        * self.cell_width_x_m[i]
                        * self.muscl_normal_velocity_z[i, j, face]
                    )
                else:
                    area = self.cell_width_x_m[i] * self.cell_width_y_m[j]
                    if face == 0:
                        q_minus = self.muscl_normal_velocity_z[i, j, 0] * area
                    elif self.obstacle[i, j, face - 1] == 0:
                        q_minus = 0.5 * area * (
                            self.muscl_normal_velocity_z[i, j, face - 1]
                            + self.muscl_normal_velocity_z[i, j, face]
                        )
                self.muscl_momentum_volume_flux_z_half_m3_s[
                    i, j, face, component, 0
                ] = q_minus
                self.muscl_momentum_volume_flux_z_half_m3_s[
                    i, j, face, component, 1
                ] = q_plus
                flux[component] = q_minus * (
                    left[component] if q_minus >= 0.0 else right[component]
                ) + q_plus * (
                    left[component] if q_plus >= 0.0 else right[component]
                )
            self.muscl_momentum_flux_z[i, j, face] = flux

    def _compute_muscl_primal_normal_velocity_ledger(
        self,
        source: object,
        wall_flag_codes: tuple[int, int, int, int, int, int],
        *,
        pressure_outlet_zmin: bool = False,
        velocity_inlet_zmax: bool | None = None,
    ) -> None:
        """Build the authoritative scalar primal-face relative-Q ledger."""
        mode = self._resolve_physical_face_topology(
            pressure_outlet_zmin=pressure_outlet_zmin,
            velocity_inlet_zmax=velocity_inlet_zmax,
            wall_flag_codes=wall_flag_codes,
        )
        outlet = 1 if pressure_outlet_zmin else 0
        self._compute_muscl_primal_normal_velocity_x_kernel(source, outlet, mode)
        self._compute_muscl_primal_normal_velocity_y_kernel(source, outlet, mode)
        self._compute_muscl_primal_normal_velocity_z_kernel(source, outlet, mode)

    def _compute_muscl_momentum_fluxes(
        self,
        source: object,
        wall_flag_codes: tuple[int, int, int, int, int, int],
        *,
        dual_geometry_prepared: bool = False,
        pressure_outlet_zmin: bool = False,
        velocity_inlet_zmax: bool | None = None,
    ) -> None:
        # Reject an inconsistent topology before synchronizing source rows.
        mode = self._resolve_physical_face_topology(
            pressure_outlet_zmin=pressure_outlet_zmin,
            velocity_inlet_zmax=velocity_inlet_zmax,
            wall_flag_codes=wall_flag_codes,
        )
        # The minimum-side normal compact rows are colocated with physical
        # boundary faces.  Synchronize them before slope/state construction so
        # stale packed values cannot enter the first RK flux.  Plus-side faces
        # have no compact owner and remain ledger-only by design.
        self._synchronize_muscl_minimum_normal_boundary_rows_kernel(
            source, int(pressure_outlet_zmin), mode,
        )
        # An immersed A/B owner is also a native MAC face state.  Restore its
        # strict target before slopes and upwind states are formed; clamping
        # only after a stage cannot undo momentum already sent to a neighbour.
        self._synchronize_muscl_exact_interface_owner_kernel(
            source,
            self._velocity_dirichlet_boundary_authority_code(),
        )
        # Phase 1: build the one authoritative scalar primal-face relative
        # volume-velocity ledger.  SST scalar transport consumes these same
        # face velocities; immersed moving-wall faces are closed in relative
        # coordinates and exact external faces retain their directed target.
        self._compute_muscl_primal_normal_velocity_ledger(
            source, wall_flag_codes,
            pressure_outlet_zmin=pressure_outlet_zmin,
            velocity_inlet_zmax=velocity_inlet_zmax,
        )
        if not dual_geometry_prepared:
            self._compute_muscl_momentum_dual_geometry_kernel()
        for axis in range(3):
            self._prepare_muscl_velocity_axis_reconstruction_kernel(source, axis)
        # Phase 2: lift each scalar primal flux into the three component-native
        # MAC dual ledgers.  Transverse faces preserve both graded half areas
        # and upwind each signed half independently before summation.
        self._compute_muscl_momentum_flux_x_kernel(
            source, wall_flag_codes[0], wall_flag_codes[1],
            int(pressure_outlet_zmin), mode,
        )
        self._compute_muscl_momentum_flux_y_kernel(
            source, wall_flag_codes[2], wall_flag_codes[3],
            int(pressure_outlet_zmin), mode,
        )
        self._compute_muscl_momentum_flux_z_kernel(
            source, wall_flag_codes[4], wall_flag_codes[5],
            int(pressure_outlet_zmin), mode,
        )

    def _prepare_muscl_sst_reconstruction(self) -> None:
        for axis in range(3):
            self._prepare_muscl_scalar_axis_reconstruction_kernel(
                self.sst_turbulent_kinetic_energy_prev,
                self.muscl_sst_k_slope,
                self.muscl_sst_k_smooth_mask,
                self.muscl_sst_k_extension_slope,
                axis,
            )
            self._prepare_muscl_scalar_axis_reconstruction_kernel(
                self.sst_specific_dissipation_rate_prev,
                self.muscl_sst_omega_slope,
                self.muscl_sst_omega_smooth_mask,
                self.muscl_sst_omega_extension_slope,
                axis,
            )

    @ti.kernel
    def _muscl_momentum_ssp_stage_device_kernel(
        self,
        source: ti.template(),
        dt_s: ti.f32,
        final_stage: ti.i32,
        canonical_authority: ti.template(),
    ):
        for i, j, k in self.velocity:
            updated = ti.Vector([0.0, 0.0, 0.0])
            for component in ti.static(range(3)):
                minus_fluid = 0
                plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                has_minus_neighbor = 0
                if ti.static(component == 0):
                    if i > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i - 1, j, k] == 0 else 0
                elif ti.static(component == 1):
                    if j > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j - 1, k] == 0 else 0
                else:
                    if k > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j, k - 1] == 0 else 0

                physical_interface = (
                    has_minus_neighbor != 0 and minus_fluid != plus_fluid
                )
                component_bit = 1 << component
                canonical_exact_owner = 0
                if ti.static(canonical_authority == 1):
                    if (
                        self._canonical_hibm_exact_component_owner(
                            i, j, k, component
                        )
                    ) != 0:
                        canonical_exact_owner = 1
                if canonical_exact_owner != 0:
                    updated[component] = (
                        self.velocity_dirichlet_boundary_value_mps[i, j, k][
                            component
                        ]
                    )
                elif physical_interface:
                    # Strict exact owners were synchronized to their target
                    # before flux construction.  A soft active owner, however,
                    # must retain the already-applied source value: the generic
                    # post-stage dispatch deliberately preserves projected soft
                    # rows and cannot recreate a value erased here.  Only a
                    # truly unowned impermeable face is fail-closed to zero.
                    active_owner = 0
                    if ti.static(canonical_authority == 1):
                        if (
                            self.velocity_dirichlet_boundary_active_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        ) != 0:
                            active_owner = 1
                    else:
                        if self.velocity_dirichlet_boundary_active[i, j, k] != 0:
                            active_owner = 1
                    updated[component] = (
                        source[i, j, k][component]
                        if active_owner != 0
                        else 0.0
                    )
                else:
                    dual_volume = self.muscl_momentum_dual_volume_m3[
                        i, j, k, component
                    ]
                    if dual_volume > 1.0e-30:
                        integrated_momentum_divergence = (
                            self.muscl_momentum_flux_x[i + 1, j, k][component]
                            - self.muscl_momentum_flux_x[i, j, k][component]
                            + self.muscl_momentum_flux_y[i, j + 1, k][component]
                            - self.muscl_momentum_flux_y[i, j, k][component]
                            + self.muscl_momentum_flux_z[i, j, k + 1][component]
                            - self.muscl_momentum_flux_z[i, j, k][component]
                        )
                        integrated_volume_divergence = 0.0
                        for half in ti.static(range(2)):
                            integrated_volume_divergence += (
                                self.muscl_momentum_volume_flux_x_half_m3_s[
                                    i + 1, j, k, component, half
                                ]
                                - self.muscl_momentum_volume_flux_x_half_m3_s[
                                    i, j, k, component, half
                                ]
                                + self.muscl_momentum_volume_flux_y_half_m3_s[
                                    i, j + 1, k, component, half
                                ]
                                - self.muscl_momentum_volume_flux_y_half_m3_s[
                                    i, j, k, component, half
                                ]
                                + self.muscl_momentum_volume_flux_z_half_m3_s[
                                    i, j, k + 1, component, half
                                ]
                                - self.muscl_momentum_volume_flux_z_half_m3_s[
                                    i, j, k, component, half
                                ]
                            )
                        # Use exactly the same integrated dual Q for both
                        # div(Q*u) and the finite-continuity correction.  This
                        # keeps a constant component invariant on graded MAC
                        # volumes even when the projected Q ledger has residual
                        # divergence.
                        advective_derivative = (
                            integrated_momentum_divergence
                            - source[i, j, k][component]
                            * integrated_volume_divergence
                        ) / dual_volume
                        candidate = (
                            source[i, j, k][component]
                            - dt_s * advective_derivative
                        )
                        if final_stage != 0:
                            updated[component] = 0.5 * (
                                self.velocity_transport_base[i, j, k][component]
                                + candidate
                            )
                        else:
                            updated[component] = candidate
            self.velocity[i, j, k] = updated

    @ti.kernel
    def _synchronize_muscl_exact_interface_owner_kernel(
        self,
        field: ti.template(),
        canonical_authority: ti.template(),
    ):
        for i, j, k in field:
            value = field[i, j, k]
            for component in ti.static(range(3)):
                has_minus_neighbor = 0
                minus_fluid = 0
                if ti.static(component == 0):
                    if i > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i - 1, j, k] == 0 else 0
                elif ti.static(component == 1):
                    if j > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j - 1, k] == 0 else 0
                else:
                    if k > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j, k - 1] == 0 else 0
                plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                physical_interface = (
                    has_minus_neighbor != 0 and minus_fluid != plus_fluid
                )
                component_bit = 1 << component
                target = self.velocity_dirichlet_boundary_value_mps[i, j, k][
                    component
                ]
                contract_tolerance = ti.cast(1.0e-6, ti.f32)
                target_is_finite = not (
                    ti.math.isnan(target) or ti.math.isinf(target)
                )
                exact_owner = 0
                if ti.static(canonical_authority == 1):
                    if (
                        self._canonical_hibm_exact_component_owner(
                            i, j, k, component
                        )
                    ) != 0:
                        exact_owner = 1
                    pressure_mobility = (
                        self.velocity_dirichlet_boundary_pressure_mobility[
                            i, j, k
                        ][component]
                    )
                    enforcement_weight = (
                        self.velocity_dirichlet_boundary_component_enforcement_weight[
                            i, j, k
                        ][component]
                    )
                    mobility_is_closed = (
                        not ti.math.isnan(pressure_mobility)
                        and not ti.math.isinf(pressure_mobility)
                        and ti.abs(pressure_mobility) <= contract_tolerance
                    )
                    enforcement_is_exact = (
                        not ti.math.isnan(enforcement_weight)
                        and not ti.math.isinf(enforcement_weight)
                        and ti.abs(enforcement_weight - 1.0) <= contract_tolerance
                    )
                    if (
                        physical_interface
                        and (
                            self.velocity_dirichlet_boundary_active_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        )
                        != 0
                        and (
                            self.velocity_dirichlet_boundary_hard_fixed_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        )
                        != 0
                        and (
                            self.velocity_dirichlet_boundary_owned_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        )
                        != 0
                        and (
                            self.velocity_dirichlet_boundary_external_exact_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        )
                        == 0
                        and mobility_is_closed
                        and enforcement_is_exact
                        and target_is_finite
                    ):
                        exact_owner = 1
                else:
                    enforcement_weight = (
                        self.velocity_dirichlet_boundary_enforcement_weight[i, j, k]
                    )
                    enforcement_is_exact = (
                        not ti.math.isnan(enforcement_weight)
                        and not ti.math.isinf(enforcement_weight)
                        and ti.abs(enforcement_weight - 1.0) <= contract_tolerance
                    )
                    if (
                        physical_interface
                        and self.velocity_dirichlet_boundary_active[i, j, k] != 0
                        and (
                            self.velocity_dirichlet_boundary_hard_fixed_component_mask[
                                i, j, k
                            ]
                            & component_bit
                        )
                        != 0
                        and self.velocity_dirichlet_boundary_owned_row[i, j, k] != 0
                        and enforcement_is_exact
                        and target_is_finite
                    ):
                        exact_owner = 1
                if exact_owner != 0:
                    # Canonical owner orientation is independent of the scalar
                    # cell phase.  A B owner is stored on the obstacle row and
                    # therefore must be synchronized before reconstruction as
                    # well as restored after the generic stage.
                    value[component] = target
            field[i, j, k] = value

    def _muscl_momentum_ssp_stage_kernel(
        self,
        source: object,
        dt_s: float,
        final_stage: int,
        wall_flag_codes: tuple[int, int, int, int, int, int] = (0, 0, 0, 0, 0, 0),
        *,
        pressure_outlet_zmin: bool = False,
        velocity_inlet_zmax: bool | None = None,
    ) -> None:
        """Launch one dual-CV stage with compile-time boundary authority."""

        mode = self._resolve_physical_face_topology(
            pressure_outlet_zmin=pressure_outlet_zmin,
            velocity_inlet_zmax=velocity_inlet_zmax,
            wall_flag_codes=wall_flag_codes,
        )
        self._muscl_momentum_ssp_stage_device_kernel(
            source,
            float(dt_s),
            int(final_stage),
            self._velocity_dirichlet_boundary_authority_code(),
        )
        # Restore the physical minimum-side normals before the next RK source
        # copy/rate evaluation.  This complements the pre-flux synchronization:
        # either one alone leaves one stage exposed to stale packed data.
        self._synchronize_muscl_minimum_normal_boundary_rows_kernel(
            self.velocity, int(pressure_outlet_zmin), mode,
        )
        self._synchronize_muscl_exact_interface_owner_kernel(
            self.velocity,
            self._velocity_dirichlet_boundary_authority_code()
        )

    @ti.kernel
    def _muscl_momentum_advection_rate_kernel(self) -> ti.f64:
        self.reduction_max[None] = 0.0
        for i, j, k in self.velocity:
            for component in ti.static(range(3)):
                dual_volume = self.muscl_momentum_dual_volume_m3[
                    i, j, k, component
                ]
                minus_fluid = 0
                plus_fluid = 1 if self.obstacle[i, j, k] == 0 else 0
                has_minus_neighbor = 0
                if ti.static(component == 0):
                    if i > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i - 1, j, k] == 0 else 0
                elif ti.static(component == 1):
                    if j > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j - 1, k] == 0 else 0
                else:
                    if k > 0:
                        has_minus_neighbor = 1
                        minus_fluid = 1 if self.obstacle[i, j, k - 1] == 0 else 0
                physical_interface = (
                    has_minus_neighbor != 0 and minus_fluid != plus_fluid
                )
                canonical_exact_owner = (
                    self._canonical_hibm_exact_component_owner(
                        i, j, k, component
                    )
                ) != 0
                if (
                    dual_volume > 1.0e-30
                    and not physical_interface
                    and not canonical_exact_owner
                ):
                    x_out = 0.0
                    x_in = 0.0
                    y_out = 0.0
                    y_in = 0.0
                    z_out = 0.0
                    z_in = 0.0
                    for half in ti.static(range(2)):
                        x_minus = self.muscl_momentum_volume_flux_x_half_m3_s[
                            i, j, k, component, half
                        ]
                        x_plus = self.muscl_momentum_volume_flux_x_half_m3_s[
                            i + 1, j, k, component, half
                        ]
                        y_minus = self.muscl_momentum_volume_flux_y_half_m3_s[
                            i, j, k, component, half
                        ]
                        y_plus = self.muscl_momentum_volume_flux_y_half_m3_s[
                            i, j + 1, k, component, half
                        ]
                        z_minus = self.muscl_momentum_volume_flux_z_half_m3_s[
                            i, j, k, component, half
                        ]
                        z_plus = self.muscl_momentum_volume_flux_z_half_m3_s[
                            i, j, k + 1, component, half
                        ]
                        # Never collapse signed halves before the CFL bound:
                        # counterflow can have zero net Q while carrying both
                        # inward and outward characteristics at finite speed.
                        x_out += ti.max(-x_minus, 0.0) + ti.max(x_plus, 0.0)
                        x_in += ti.max(x_minus, 0.0) + ti.max(-x_plus, 0.0)
                        y_out += ti.max(-y_minus, 0.0) + ti.max(y_plus, 0.0)
                        y_in += ti.max(y_minus, 0.0) + ti.max(-y_plus, 0.0)
                        z_out += ti.max(-z_minus, 0.0) + ti.max(z_plus, 0.0)
                        z_in += ti.max(z_minus, 0.0) + ti.max(-z_plus, 0.0)
                    local_rate = (
                        ti.max(x_out, x_in)
                        + ti.max(y_out, y_in)
                        + ti.max(z_out, z_in)
                    ) / dual_volume
                    ti.atomic_max(
                        self.reduction_max[None], ti.cast(local_rate, ti.f64)
                    )
        return self.reduction_max[None]

    @ti.kernel
    def _muscl_scalar_face_advection_rate_kernel(self) -> ti.f64:
        """Return the primal scalar-CV rate used only by SST transport."""

        self.reduction_max[None] = 0.0
        for i, j, k in self.velocity:
            if self.obstacle[i, j, k] == 0:
                x_minus = self.muscl_normal_velocity_x[i, j, k]
                x_plus = self.muscl_normal_velocity_x[i + 1, j, k]
                y_minus = self.muscl_normal_velocity_y[i, j, k]
                y_plus = self.muscl_normal_velocity_y[i, j + 1, k]
                z_minus = self.muscl_normal_velocity_z[i, j, k]
                z_plus = self.muscl_normal_velocity_z[i, j, k + 1]
                x_out = ti.max(-x_minus, 0.0) + ti.max(x_plus, 0.0)
                x_in = ti.max(x_minus, 0.0) + ti.max(-x_plus, 0.0)
                y_out = ti.max(-y_minus, 0.0) + ti.max(y_plus, 0.0)
                y_in = ti.max(y_minus, 0.0) + ti.max(-y_plus, 0.0)
                z_out = ti.max(-z_minus, 0.0) + ti.max(z_plus, 0.0)
                z_in = ti.max(z_minus, 0.0) + ti.max(-z_plus, 0.0)
                local_rate = (
                    ti.max(x_out, x_in) / self.cell_width_x_m[i]
                    + ti.max(y_out, y_in) / self.cell_width_y_m[j]
                    + ti.max(z_out, z_in) / self.cell_width_z_m[k]
                )
                ti.atomic_max(self.reduction_max[None], ti.cast(local_rate, ti.f64))
        return self.reduction_max[None]

    def _muscl_momentum_advection_rate_s(self) -> float:
        """Return the current physical-face transport rate to the host controller."""

        return float(self._muscl_momentum_advection_rate_kernel())

    def _muscl_invalid_rate_diagnostics(self) -> str:
        """Describe a failed transport rate without adding normal-path transfers."""

        def _array_summary(name: str, values: np.ndarray) -> str:
            array = np.asarray(values)
            finite_mask = np.isfinite(array)
            nonfinite_count = int(array.size - np.count_nonzero(finite_mask))
            if np.any(finite_mask):
                finite_abs = np.where(finite_mask, np.abs(array), -1.0)
                flat_index = int(np.argmax(finite_abs))
                maximum_index = tuple(
                    int(index) for index in np.unravel_index(flat_index, array.shape)
                )
                maximum_abs = float(finite_abs.reshape(-1)[flat_index])
            else:
                maximum_index = ()
                maximum_abs = float("nan")
            first_nonfinite_index: tuple[int, ...] = ()
            if nonfinite_count:
                first_nonfinite_index = tuple(
                    int(index)
                    for index in np.argwhere(~finite_mask)[0]
                )
            return (
                f"{name}_nonfinite_count={nonfinite_count}, "
                f"{name}_max_abs={maximum_abs:g}, "
                f"{name}_max_abs_index={maximum_index}, "
                f"{name}_first_nonfinite_index={first_nonfinite_index}"
            )

        return "; ".join(
            (
                _array_summary("velocity", self.velocity.to_numpy()),
                _array_summary(
                    "normal_face_x", self.muscl_normal_velocity_x.to_numpy()
                ),
                _array_summary(
                    "normal_face_y", self.muscl_normal_velocity_y.to_numpy()
                ),
                _array_summary(
                    "normal_face_z", self.muscl_normal_velocity_z.to_numpy()
                ),
            )
        )

    @ti.func
    def _storage_path_crosses_obstacle_or_canonical_hibm_wall(
        self,
        i,
        j,
        k,
        target_i,
        target_j,
        target_k,
    ):
        """Fail closed when a storage-cell path crosses an obstacle or hard face."""

        blocked = 0
        delta_i = ti.abs(target_i - i)
        delta_j = ti.abs(target_j - j)
        delta_k = ti.abs(target_k - k)
        steps = ti.max(delta_i, ti.max(delta_j, delta_k))
        march_steps = ti.min(steps, PREDICTOR_BACKTRACE_OBSTACLE_MARCH_MAX_STEPS)
        previous_i = i
        previous_j = j
        previous_k = k
        step = 1
        while step <= march_steps:
            fraction = ti.cast(step, ti.f32) / ti.cast(march_steps, ti.f32)
            sample_i = ti.min(
                ti.max(
                    ti.floor(
                        ti.cast(i, ti.f32)
                        + ti.cast(target_i - i, ti.f32) * fraction
                        + 0.5,
                        ti.i32,
                    ),
                    0,
                ),
                self.nx - 1,
            )
            sample_j = ti.min(
                ti.max(
                    ti.floor(
                        ti.cast(j, ti.f32)
                        + ti.cast(target_j - j, ti.f32) * fraction
                        + 0.5,
                        ti.i32,
                    ),
                    0,
                ),
                self.ny - 1,
            )
            sample_k = ti.min(
                ti.max(
                    ti.floor(
                        ti.cast(k, ti.f32)
                        + ti.cast(target_k - k, ti.f32) * fraction
                        + 0.5,
                        ti.i32,
                    ),
                    0,
                ),
                self.nz - 1,
            )
            if self.obstacle[sample_i, sample_j, sample_k] != 0:
                blocked = 1
            if sample_i != previous_i:
                face_i = ti.max(sample_i, previous_i)
                for transverse_j, transverse_k in ti.ndrange(2, 2):
                    candidate_j = previous_j if transverse_j == 0 else sample_j
                    candidate_k = previous_k if transverse_k == 0 else sample_k
                    if self.canonical_exact_hard_face_component_mask[face_i, candidate_j, candidate_k] & 1 != 0:
                        blocked = 1
            if sample_j != previous_j:
                face_j = ti.max(sample_j, previous_j)
                for transverse_i, transverse_k in ti.ndrange(2, 2):
                    candidate_i = previous_i if transverse_i == 0 else sample_i
                    candidate_k = previous_k if transverse_k == 0 else sample_k
                    if self.canonical_exact_hard_face_component_mask[candidate_i, face_j, candidate_k] & 2 != 0:
                        blocked = 1
            if sample_k != previous_k:
                face_k = ti.max(sample_k, previous_k)
                for transverse_i, transverse_j in ti.ndrange(2, 2):
                    candidate_i = previous_i if transverse_i == 0 else sample_i
                    candidate_j = previous_j if transverse_j == 0 else sample_j
                    if self.canonical_exact_hard_face_component_mask[candidate_i, candidate_j, face_k] & 4 != 0:
                        blocked = 1
            previous_i = sample_i
            previous_j = sample_j
            previous_k = sample_k
            step += 1
        return blocked

    @ti.func
    def _storage_corner_path_crosses_obstacle_or_canonical_hibm_wall(
        self,
        anchor_i,
        anchor_j,
        anchor_k,
        sample_i,
        sample_j,
        sample_k,
    ):
        blocked = 0
        if (
            self.obstacle[anchor_i, anchor_j, anchor_k] != 0
            or self.obstacle[sample_i, sample_j, sample_k] != 0
        ):
            blocked = 1
        if sample_i != anchor_i:
            face_i = sample_i if sample_i > anchor_i else anchor_i
            for transverse_j, transverse_k in ti.ndrange(2, 2):
                candidate_j = anchor_j if transverse_j == 0 else sample_j
                candidate_k = anchor_k if transverse_k == 0 else sample_k
                if self.canonical_exact_hard_face_component_mask[face_i, candidate_j, candidate_k] & 1 != 0:
                    blocked = 1
        if sample_j != anchor_j:
            face_j = sample_j if sample_j > anchor_j else anchor_j
            for transverse_i, transverse_k in ti.ndrange(2, 2):
                candidate_i = anchor_i if transverse_i == 0 else sample_i
                candidate_k = anchor_k if transverse_k == 0 else sample_k
                if self.canonical_exact_hard_face_component_mask[candidate_i, face_j, candidate_k] & 2 != 0:
                    blocked = 1
        if sample_k != anchor_k:
            face_k = sample_k if sample_k > anchor_k else anchor_k
            for transverse_i, transverse_j in ti.ndrange(2, 2):
                candidate_i = anchor_i if transverse_i == 0 else sample_i
                candidate_j = anchor_j if transverse_j == 0 else sample_j
                if self.canonical_exact_hard_face_component_mask[candidate_i, candidate_j, face_k] & 4 != 0:
                    blocked = 1
        return blocked

    @ti.func
    def _sample_velocity_prev_trilinear(self, x, y, z, fallback):
        """Sample each backward-MAC component at the same physical point."""
        value = ti.Vector([0.0, 0.0, 0.0])
        # Visibility belongs to primal cells, independently of MAC interpolation.
        anchor_i = self._cell_index_from_faces_device(x, self.cell_face_x_m, self.nx)
        anchor_j = self._cell_index_from_faces_device(y, self.cell_face_y_m, self.ny)
        anchor_k = self._cell_index_from_faces_device(z, self.cell_face_z_m, self.nz)
        for component in range(3):
            coordinate = self._mac_grid_coordinates_at(x, y, z, component)
            gx, gy, gz = coordinate.x, coordinate.y, coordinate.z
            i0 = ti.min(ti.max(ti.floor(gx, ti.i32), 0), self.nx - 2)
            j0 = ti.min(ti.max(ti.floor(gy, ti.i32), 0), self.ny - 2)
            k0 = ti.min(ti.max(ti.floor(gz, ti.i32), 0), self.nz - 2)
            tx = ti.min(ti.max(gx - ti.cast(i0, ti.f32), 0.0), 1.0)
            ty = ti.min(ti.max(gy - ti.cast(j0, ti.f32), 0.0), 1.0)
            tz = ti.min(ti.max(gz - ti.cast(k0, ti.f32), 0.0), 1.0)
            fluid_weight = 0.0
            for oi, oj, ok in ti.ndrange(2, 2, 2):
                wx = ti.select(oi == 0, 1.0 - tx, tx)
                wy = ti.select(oj == 0, 1.0 - ty, ty)
                wz = ti.select(ok == 0, 1.0 - tz, tz)
                weight = wx * wy * wz
                sample_i = i0 + oi
                sample_j = j0 + oj
                sample_k = k0 + ok
                if (
                    self.obstacle[sample_i, sample_j, sample_k] == 0
                    and self._storage_corner_path_crosses_obstacle_or_canonical_hibm_wall(
                        anchor_i,
                        anchor_j,
                        anchor_k,
                        sample_i,
                        sample_j,
                        sample_k,
                    )
                    == 0
                ):
                    value[component] += weight * self.velocity_prev[sample_i, sample_j, sample_k][component]
                    fluid_weight += weight
            if fluid_weight > 1.0e-12:
                value[component] /= fluid_weight
            else:
                value[component] = fallback[component]
        return value

    @ti.func
    def _axis_grid_coordinate_device(
        self,
        value,
        faces: ti.template(),
        centers: ti.template(),
        count: ti.i32,
    ):
        coordinate = 0.0
        if value <= centers[0]:
            half_width = ti.max(centers[0] - faces[0], 1.0e-18)
            coordinate = -0.5 * (centers[0] - value) / half_width
        elif value >= centers[count - 1]:
            half_width = ti.max(faces[count] - centers[count - 1], 1.0e-18)
            coordinate = ti.cast(count - 1, ti.f32) + 0.5 * (value - centers[count - 1]) / half_width
        else:
            lower = 0
            upper = count - 1
            while upper - lower > 1:
                middle = (lower + upper) // 2
                if value >= centers[middle]:
                    lower = middle
                else:
                    upper = middle
            upper = ti.min(lower + 1, count - 1)
            distance = ti.max(centers[upper] - centers[lower], 1.0e-18)
            coordinate = ti.cast(lower, ti.f32) + (value - centers[lower]) / distance
        return coordinate

    @ti.func
    def _grid_coordinate_x(self, x):
        return self._axis_grid_coordinate_device(x, self.cell_face_x_m, self.cell_center_x_m, self.nx)

    @ti.func
    def _grid_coordinate_y(self, y):
        return self._axis_grid_coordinate_device(y, self.cell_face_y_m, self.cell_center_y_m, self.ny)

    @ti.func
    def _grid_coordinate_z(self, z):
        return self._axis_grid_coordinate_device(z, self.cell_face_z_m, self.cell_center_z_m, self.nz)

    @ti.func
    def _mac_grid_coordinates_at(self, x, y, z, component):
        coordinate = ti.Vector([
            self._grid_coordinate_x(x),
            self._grid_coordinate_y(y),
            self._grid_coordinate_z(z),
        ])
        # The stored normal component is on faces[0:count], including on graded
        # grids. Clamp first so the existing inverse uses only stored positions.
        if component == 0:
            coordinate.x = self._axis_grid_coordinate_device(
                ti.min(ti.max(x, self.cell_face_x_m[0]), self.cell_face_x_m[self.nx - 1]),
                self.cell_face_x_m, self.cell_face_x_m, self.nx,
            )
        elif component == 1:
            coordinate.y = self._axis_grid_coordinate_device(
                ti.min(ti.max(y, self.cell_face_y_m[0]), self.cell_face_y_m[self.ny - 1]),
                self.cell_face_y_m, self.cell_face_y_m, self.ny,
            )
        else:
            coordinate.z = self._axis_grid_coordinate_device(
                ti.min(ti.max(z, self.cell_face_z_m[0]), self.cell_face_z_m[self.nz - 1]),
                self.cell_face_z_m, self.cell_face_z_m, self.nz,
            )
        return coordinate

    @ti.func
    def _sst_scalar_derivative_x(self, field: ti.template(), i, j, k):
        value = 0.0
        has_minus = i > 0 and self.obstacle[i - 1, j, k] == 0
        has_plus = i + 1 < self.nx and self.obstacle[i + 1, j, k] == 0
        if has_minus and has_plus:
            distance = self.center_distance_x_m[i] + self.center_distance_x_m[i + 1]
            value = (field[i + 1, j, k] - field[i - 1, j, k]) / distance
        elif has_plus:
            value = (field[i + 1, j, k] - field[i, j, k]) / self.center_distance_x_m[i + 1]
        elif has_minus:
            value = (field[i, j, k] - field[i - 1, j, k]) / self.center_distance_x_m[i]
        return value

    @ti.func
    def _sst_scalar_derivative_y(self, field: ti.template(), i, j, k):
        value = 0.0
        has_minus = j > 0 and self.obstacle[i, j - 1, k] == 0
        has_plus = j + 1 < self.ny and self.obstacle[i, j + 1, k] == 0
        if has_minus and has_plus:
            distance = self.center_distance_y_m[j] + self.center_distance_y_m[j + 1]
            value = (field[i, j + 1, k] - field[i, j - 1, k]) / distance
        elif has_plus:
            value = (field[i, j + 1, k] - field[i, j, k]) / self.center_distance_y_m[j + 1]
        elif has_minus:
            value = (field[i, j, k] - field[i, j - 1, k]) / self.center_distance_y_m[j]
        return value

    @ti.func
    def _sst_scalar_derivative_z(self, field: ti.template(), i, j, k):
        value = 0.0
        has_minus = k > 0 and self.obstacle[i, j, k - 1] == 0
        has_plus = k + 1 < self.nz and self.obstacle[i, j, k + 1] == 0
        if has_minus and has_plus:
            distance = self.center_distance_z_m[k] + self.center_distance_z_m[k + 1]
            value = (field[i, j, k + 1] - field[i, j, k - 1]) / distance
        elif has_plus:
            value = (field[i, j, k + 1] - field[i, j, k]) / self.center_distance_z_m[k + 1]
        elif has_minus:
            value = (field[i, j, k] - field[i, j, k - 1]) / self.center_distance_z_m[k]
        return value

    @ti.func
    def _sst_local_wall_velocity(self, i, j, k):
        value = ti.Vector([0.0, 0.0, 0.0])
        if self.velocity_dirichlet_boundary_active[i, j, k] != 0:
            value = self.velocity_dirichlet_boundary_value_mps[i, j, k]
        return value

    @ti.func
    def _sst_vector_component(self, value, component_index):
        result = value.x
        if component_index == 1:
            result = value.y
        elif component_index == 2:
            result = value.z
        return result

    @ti.func
    def _sst_wall_target_derivative_x(self, i, j, k, component_index):
        value = 0.0
        current_active = self.velocity_dirichlet_boundary_active[i, j, k] != 0
        has_minus = (
            current_active
            and i > 0
            and self.velocity_dirichlet_boundary_active[i - 1, j, k] != 0
        )
        has_plus = (
            current_active
            and i + 1 < self.nx
            and self.velocity_dirichlet_boundary_active[i + 1, j, k] != 0
        )
        center = self._sst_vector_component(
            self.velocity_dirichlet_boundary_value_mps[i, j, k], component_index
        )
        if has_minus and has_plus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i - 1, j, k],
                component_index,
            )
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i + 1, j, k],
                component_index,
            )
            value = (plus - minus) / (
                self.center_distance_x_m[i] + self.center_distance_x_m[i + 1]
            )
        elif has_plus:
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i + 1, j, k],
                component_index,
            )
            value = (plus - center) / self.center_distance_x_m[i + 1]
        elif has_minus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i - 1, j, k],
                component_index,
            )
            value = (center - minus) / self.center_distance_x_m[i]
        return value

    @ti.func
    def _sst_wall_target_derivative_y(self, i, j, k, component_index):
        value = 0.0
        current_active = self.velocity_dirichlet_boundary_active[i, j, k] != 0
        has_minus = (
            current_active
            and j > 0
            and self.velocity_dirichlet_boundary_active[i, j - 1, k] != 0
        )
        has_plus = (
            current_active
            and j + 1 < self.ny
            and self.velocity_dirichlet_boundary_active[i, j + 1, k] != 0
        )
        center = self._sst_vector_component(
            self.velocity_dirichlet_boundary_value_mps[i, j, k], component_index
        )
        if has_minus and has_plus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j - 1, k],
                component_index,
            )
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j + 1, k],
                component_index,
            )
            value = (plus - minus) / (
                self.center_distance_y_m[j] + self.center_distance_y_m[j + 1]
            )
        elif has_plus:
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j + 1, k],
                component_index,
            )
            value = (plus - center) / self.center_distance_y_m[j + 1]
        elif has_minus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j - 1, k],
                component_index,
            )
            value = (center - minus) / self.center_distance_y_m[j]
        return value

    @ti.func
    def _sst_wall_target_derivative_z(self, i, j, k, component_index):
        value = 0.0
        current_active = self.velocity_dirichlet_boundary_active[i, j, k] != 0
        has_minus = (
            current_active
            and k > 0
            and self.velocity_dirichlet_boundary_active[i, j, k - 1] != 0
        )
        has_plus = (
            current_active
            and k + 1 < self.nz
            and self.velocity_dirichlet_boundary_active[i, j, k + 1] != 0
        )
        center = self._sst_vector_component(
            self.velocity_dirichlet_boundary_value_mps[i, j, k], component_index
        )
        if has_minus and has_plus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j, k - 1],
                component_index,
            )
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j, k + 1],
                component_index,
            )
            value = (plus - minus) / (
                self.center_distance_z_m[k] + self.center_distance_z_m[k + 1]
            )
        elif has_plus:
            plus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j, k + 1],
                component_index,
            )
            value = (plus - center) / self.center_distance_z_m[k + 1]
        elif has_minus:
            minus = self._sst_vector_component(
                self.velocity_dirichlet_boundary_value_mps[i, j, k - 1],
                component_index,
            )
            value = (center - minus) / self.center_distance_z_m[k]
        return value

    @ti.func
    def _sst_external_x_normal_target_derivative_y(self, side, j, k):
        value = 0.0
        has_minus = j > 0 and (
            self.external_velocity_boundary_x_face_active_component_mask[
                side, j - 1, k
            ]
            & 1
        ) != 0
        has_plus = j + 1 < self.ny and (
            self.external_velocity_boundary_x_face_active_component_mask[
                side, j + 1, k
            ]
            & 1
        ) != 0
        center = self.external_velocity_boundary_x_face_value_mps[side, j, k].x
        if has_minus and has_plus:
            value = (
                self.external_velocity_boundary_x_face_value_mps[side, j + 1, k].x
                - self.external_velocity_boundary_x_face_value_mps[side, j - 1, k].x
            ) / (self.center_distance_y_m[j] + self.center_distance_y_m[j + 1])
        elif has_plus:
            value = (
                self.external_velocity_boundary_x_face_value_mps[side, j + 1, k].x
                - center
            ) / self.center_distance_y_m[j + 1]
        elif has_minus:
            value = (
                center
                - self.external_velocity_boundary_x_face_value_mps[side, j - 1, k].x
            ) / self.center_distance_y_m[j]
        return value

    @ti.func
    def _sst_external_x_normal_target_derivative_z(self, side, j, k):
        value = 0.0
        has_minus = k > 0 and (
            self.external_velocity_boundary_x_face_active_component_mask[
                side, j, k - 1
            ]
            & 1
        ) != 0
        has_plus = k + 1 < self.nz and (
            self.external_velocity_boundary_x_face_active_component_mask[
                side, j, k + 1
            ]
            & 1
        ) != 0
        center = self.external_velocity_boundary_x_face_value_mps[side, j, k].x
        if has_minus and has_plus:
            value = (
                self.external_velocity_boundary_x_face_value_mps[side, j, k + 1].x
                - self.external_velocity_boundary_x_face_value_mps[side, j, k - 1].x
            ) / (self.center_distance_z_m[k] + self.center_distance_z_m[k + 1])
        elif has_plus:
            value = (
                self.external_velocity_boundary_x_face_value_mps[side, j, k + 1].x
                - center
            ) / self.center_distance_z_m[k + 1]
        elif has_minus:
            value = (
                center
                - self.external_velocity_boundary_x_face_value_mps[side, j, k - 1].x
            ) / self.center_distance_z_m[k]
        return value

